CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS "pg_trgm";


CREATE TABLE IF NOT EXISTS pezeshkan_pillars (
    id SERIAL PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    short_name VARCHAR(100),
    slug VARCHAR(100) UNIQUE NOT NULL,
    icon VARCHAR(100),
    count_badge VARCHAR(50),
    intent VARCHAR(100),
    dept VARCHAR(100),
    description TEXT,
    chips JSONB DEFAULT '[]'::jsonb,
    branches JSONB DEFAULT '[]'::jsonb,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS pezeshkan_doctors (
    id SERIAL PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    title VARCHAR(255),
    mc_number VARCHAR(100),
    dept VARCHAR(100),
    pillar_slug VARCHAR(100),
    rating NUMERIC(3, 2) DEFAULT 5.0,
    reviews_count INT DEFAULT 0,
    avatar TEXT,
    available BOOLEAN DEFAULT TRUE,
    work_hours VARCHAR(255),
    address TEXT,
    phone VARCHAR(50),
    time_slots JSONB DEFAULT '[]'::jsonb,
    services JSONB DEFAULT '[]'::jsonb,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS pezeshkan_articles (
    id SERIAL PRIMARY KEY,
    title VARCHAR(500) NOT NULL,
    slug VARCHAR(255) UNIQUE NOT NULL,
    summary TEXT,
    raw_html TEXT,
    content_html TEXT,
    image TEXT,
    image_alt VARCHAR(500),
    pillar_id VARCHAR(50),
    category_name VARCHAR(100),
    category_icon VARCHAR(100),
    doctor_id VARCHAR(50),
    author VARCHAR(255) DEFAULT 'تیم تحریریه پزشکان',
    read_time VARCHAR(50) DEFAULT '۵ دقیقه',
    last_reviewed VARCHAR(100),
    tag VARCHAR(100),
    tag_class VARCHAR(100),
    status VARCHAR(50) DEFAULT 'published',
    meta_title VARCHAR(255),
    meta_description TEXT,
    focus_keyword VARCHAR(255),
    faqs JSONB DEFAULT '[]'::jsonb,
    schema_type VARCHAR(100) DEFAULT 'MedicalWebPage',
    old_slugs JSONB DEFAULT '[]'::jsonb,
    schema_data JSONB DEFAULT '{}'::jsonb,
    custom_schema_json TEXT,
    last_modified TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS pezeshkan_appointments (
    id SERIAL PRIMARY KEY,
    tracking_code VARCHAR(32) UNIQUE NOT NULL,
    doctor_id VARCHAR(50) NOT NULL,
    doctor_name VARCHAR(255),
    patient_name VARCHAR(255) NOT NULL,
    patient_phone VARCHAR(50) NOT NULL,
    national_id VARCHAR(50),
    date_label VARCHAR(100) NOT NULL,
    time_slot VARCHAR(100) NOT NULL,
    notes TEXT,
    status VARCHAR(50) DEFAULT 'pending',
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS pezeshkan_media (
    id SERIAL PRIMARY KEY,
    filename VARCHAR(255) NOT NULL,
    url TEXT NOT NULL,
    variants JSONB DEFAULT '{}'::jsonb,
    dimensions JSONB DEFAULT '{}'::jsonb,
    format VARCHAR(20) DEFAULT 'webp',
    size BIGINT DEFAULT 0,
    original_size BIGINT DEFAULT 0,
    saved_percentage NUMERIC(5, 2) DEFAULT 0.0,
    storage VARCHAR(50) DEFAULT 'local',
    alt VARCHAR(500),
    title VARCHAR(500),
    caption TEXT,
    uploaded_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS pezeshkan_redirects (
    id SERIAL PRIMARY KEY,
    source VARCHAR(500) UNIQUE NOT NULL,
    target VARCHAR(500) NOT NULL,
    status_code INT DEFAULT 301,
    match_type VARCHAR(50) DEFAULT 'exact',
    preserve_query BOOLEAN DEFAULT TRUE,
    is_active BOOLEAN DEFAULT TRUE,
    description TEXT,
    hit_count BIGINT DEFAULT 0,
    last_hit TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS pezeshkan_settings (
    id SERIAL PRIMARY KEY,
    site_title VARCHAR(255) DEFAULT 'پزشکان - مجله جامع سلامت',
    site_subtitle VARCHAR(255),
    editorial_leader VARCHAR(255),
    announcement_banner TEXT,
    contact_phone VARCHAR(50),
    emergency_triage_enabled BOOLEAN DEFAULT TRUE,
    seo JSONB DEFAULT '{}'::jsonb,
    last_updated TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

INSERT INTO pezeshkan_pillars (name, short_name, slug, icon, count_badge, intent, dept, description, chips, branches)
VALUES ('درد، ستون فقرات و توانبخشی', '["درد و ستون فقرات", "توانبخشی و فیزیوتراپی"]'::jsonb, '/mag/physical-rehab/', 'spine', '۳۲ خدمت تخصصی', 'درمان غیرجراحی دیسک، مفاصل و بازتوانی بالینی', 'کلینیک طب فیزیکی، توانبخشی و نوار عصب بیمارستان', 'تشخیص و درمان‌های غیرتهاجمی دیسک کمر، آرتروز، فیزیوتراپی پیشرفته و بازآموزی حرکتی بیماران', '["تکارتراپی RF", "شاک‌ویوتراپی", "لیزر پرتوان", "سوزن خشک (Dry Needling)", "تزریق PRP و اوزون", "نوار عصب EMG/NCV", "کفی طبی ۳ بعدی"]'::jsonb, '[{"title": "خدمات تشخیصی (الکترودیاگنوزیس و سونوگرافی)", "slug": "/diagnostics/", "clusters": [{"title": "نوار عصب و عضله (EMG/NCS)", "slug": "emg-ncs-test", "desc": "تشخیص درگیری ریشه عصب سیاتیک، دیسکوپاتی، سندرم تونل کارپال و پلی‌نوروپاتی دیابتی"}, {"title": "سونوگرافی عضلانی-اسکلتی (MSK)", "slug": "msk-ultrasound", "desc": "تصویربرداری زنده برای تشخیص پارگی تاندون شانه، بورسیت و هدایت سوزن تزریقات"}, {"title": "آنالیز بیومکانیکال و اسکن کف پا", "slug": "foot-scan-biomechanics", "desc": "بررسی اختلالات راه رفتن، توزیع فشار کف پا و صافی یا قوس بیش از حد پا"}]}, {"title": "مداخلات درمانی کم‌تهاجمی و تزریقات پزشک", "slug": "/interventions/", "clusters": [{"title": "تزریق پی‌آر‌پی (PRP زانو و شانه)", "slug": "prp-injection", "desc": "پلاسمای غنی از پلاکت برای درمان آرتروز زانو، پارگی تاندون روتاتور کاف و خار پاشنه"}, {"title": "پرولوتراپی رباط‌ها و تاندون‌ها", "slug": "prolotherapy", "desc": "تزریق محلول محرک دکستروز برای ترمیم رباط‌ها و رفع شل‌شدگی مفاصل"}, {"title": "اوزون‌تراپی مفاصل و ستون فقرات", "slug": "ozone-therapy", "desc": "تزریق گاز اوزون طبی برای کاهش التهاب حاد مفاصل و اطراف دیسک کمر"}, {"title": "تزریق ژل هیالورونیک اسید", "slug": "hyaluronic-joint-gel", "desc": "روان‌کاری مفاصل تخریب‌شده و غضروف‌سازی در بیماران مبتلا به آرتروز"}, {"title": "تزریق بوتاکس درمانی (میگرن و اسپاستیسیتی)", "slug": "medical-botox-injection", "desc": "درمان میگرن مزمن، سفتی عضلانی پس از سکته مغزی و کجی گردن"}, {"title": "بلوک‌های عصبی و اپیدورال ستون فقرات", "slug": "epidural-nerve-block", "desc": "تزریق اپیدورال و بلوک فاست گردنی و کمری برای درمان دردهای حاد دیسک و سیاتیک"}, {"title": "آزادسازی نقاط ماشه‌ای (Trigger Point)", "slug": "trigger-point-injection", "desc": "تزریق بی‌حسی و آزادسازی گره‌های عضلانی دردناک در شانه و کمر"}]}, {"title": "درمان‌های دستی و سوزنی", "slug": "/manual-needling/", "clusters": [{"title": "سوزن خشک (Dry Needling)", "slug": "dry-needling", "desc": "استفاده از سوزن‌های ظریف بدون دارو برای باز کردن اسپاسم‌های عمیق عضلانی"}, {"title": "طب سوزنی پزشکی (Medical Acupuncture)", "slug": "medical-acupuncture", "desc": "تحریک نقاط عصبی-عضلانی برای تعدیل سیگنال‌های درد مزمن"}, {"title": "مانیپولاسیون و درمان دستی ستون فقرات", "slug": "spinal-manipulation", "desc": "جااندازی و موبیلیزاسیون ستون فقرات و مفاصل برای اصلاح راستای اسکلتی"}]}, {"title": "مدالیته‌های پیشرفته فیزیکی و فیزیوتراپی", "slug": "/advanced-modalities/", "clusters": [{"title": "شاک‌ویوتراپی خار پاشنه و شانه", "slug": "shockwave-therapy", "desc": "امواج صوتی پرانرژی برای درمان خار پاشنه، تاندونیت کلسیفیه و تنیس البو"}, {"title": "لیزر درمانی پرتوان (High Power Laser)", "slug": "high-power-laser", "desc": "کاهش سریع درد و التهاب حاد در فتق دیسک کمر و گردن و ترمیم غضروف"}, {"title": "تکارتراپی (Tecar Therapy RF)", "slug": "tecar-therapy", "desc": "امواج رادیوفرکانسی جهت گرمایش عمقی بافت و تسریع التیام عضلات و تاندون‌ها"}, {"title": "مگنت‌تراپی و پوکی استخوان", "slug": "magnet-therapy", "desc": "میدان‌های مغناطیسی پالسی برای جوش‌خوردگی سریع‌تر استخوان و کاهش دردهای مزمن"}, {"title": "کشش ستون فقرات (Decompression)", "slug": "spinal-traction", "desc": "دستگاه کشش مکانیکی برای کاهش فشار روی دیسک‌ها و ریشه‌های عصبی سیاتیک"}]}, {"title": "برنامه‌های جامع توانبخشی و بازتوانی", "slug": "/rehabilitation/", "clusters": [{"title": "توانبخشی پس از تعویض مفصل زانو و لگن", "slug": "post-arthroplasty-rehab", "desc": "پروتکل راه رفتن و تمرینات کششی پس از جراحی پروتز مفصل"}, {"title": "توانبخشی بیماران سکته مغزی و ام‌اس", "slug": "stroke-ms-neuro-rehab", "desc": "بازآموزی عصبی-عضلانی و بهبود تعادل و توان حرکتی اندام‌های فلج‌شده"}, {"title": "توانبخشی آسیب‌های ورزشی و ACL", "slug": "sports-injury-acl-rehab", "desc": "پروتکل بازگشت ایمن ورزشکاران به مسابقات پس از ترمیم رباط صلیبی"}, {"title": "توانبخشی کف لگن و بی‌اختیاری ادرار", "slug": "pelvic-floor-rehab", "desc": "بیوفیدبک و تمرینات تقویت عضلات کف لگن برای درمان بی‌اختیاری ادرار"}]}, {"title": "تجویز ارتز، بریس و کفی طبی اختصاصی", "slug": "/orthotics/", "clusters": [{"title": "طراحی و ساخت کفی طبی با پرینت سه‌بعدی", "slug": "custom-3d-insoles", "desc": "اصلاح صافی کف پا، خار پاشنه و کوتاهی اندام بر اساس اسکن کامپیوتری"}, {"title": "تجویز انواع بریس و زانوبند Unloader", "slug": "orthopedic-braces", "desc": "کمربندهای تثبیت‌کننده مهره‌ها و زانوبندهای تخلیه‌کننده وزن برای آرتروز پیشرفته"}]}]'::jsonb)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description;
INSERT INTO pezeshkan_pillars (name, short_name, slug, icon, count_badge, intent, dept, description, chips, branches)
VALUES ('سلامت زنان، بارداری و زایمان', '["سلامت زنان", "بارداری و زایمان"]'::jsonb, '/mag/maternity-wellness/', 'maternity', '۳۸ خدمت تخصصی', 'مراقبت‌های بارداری، زایمان، زیبایی زنان و درمان نازایی', 'بلوک زایمان، درمانگاه زنان و مرکز ناباروری IVF بیمارستان', 'تقویم هفته به هفته بارداری، زایمان بدون درد، جراحی‌های زیبایی زنان و تکنیک‌های پیشرفته IVF', '["تقویم هفته به هفته", "زایمان طبیعی و سزارین", "لابیاپلاستی با لیزر", "واژینوپلاستی", "تنبلی تخمدان PCOS", "پاپ اسمیر و HPV", "مرکز ناباروری IVF"]'::jsonb, '[{"title": "مراقبت‌های دوران بارداری و زایمان", "slug": "/obstetrics/", "clusters": [{"title": "مشاوره و مراقبت‌های پیش از اقدام به بارداری", "slug": "preconception-care", "desc": "بررسی سلامت مادر، آزمایش‌های هورمونی و ژنتیک قبل از بارداری"}, {"title": "تقویم هفته به هفته بارداری (۱ تا ۴۰)", "slug": "week-by-week-pregnancy", "desc": "تغییرات جنین، مراقبت‌های ماهانه، تغذیه و آزمایش‌های سه ماهه بارداری"}, {"title": "مدیریت بارداری‌های پرخطر و پره‌اکلامپسی", "slug": "high-risk-pregnancy", "desc": "کنترل دیابت بارداری، فشار خون، بارداری دوقلو و سقط مکرر"}, {"title": "زایمان طبیعی بدون درد و سزارین", "slug": "painless-labor-c-section", "desc": "مقایسه زایمان فیزیولوژیک با اپیدورال، زایمان در آب و سزارین"}, {"title": "مراقبت‌های دوران نقاهت پس از زایمان", "slug": "postpartum-recovery", "desc": "ترمیم بخیه‌ها، سلامت رحم، مدیریت افسردگی پس از زایمان و شیردهی"}]}, {"title": "طب مادر، جنین و نوزادان (پریناتولوژی)", "slug": "/perinatology/", "clusters": [{"title": "سونوگرافی‌های تخصصی غربالگری NT و آنومالی", "slug": "fetal-anomaly-scans", "desc": "سونوگرافی تشکیل قلب، غربالگری مرحله اول و دوم و کالر داپلر جفت"}, {"title": "تست‌های تشخیصی تهاجمی آمنیوسنتز و CVS", "slug": "amniocentesis-cvs-test", "desc": "بررسی کروموزومی مایع آمنیوتیک برای سندروم داون و ناهنجاری‌ها"}, {"title": "احیا و پایش سلامت نوزاد در بدو تولد (NICU)", "slug": "neonatal-resuscitation-nicu", "desc": "نمره آپگار، ساکشن، مراقبت‌های نوزاد نارس در بخش NICU"}]}, {"title": "جراحی‌ها و خدمات زیبایی زنان", "slug": "/cosmetic-gynecology/", "clusters": [{"title": "عمل لابیاپلاستی با لیزر دیود و جراحی", "slug": "laser-labiaplasty", "desc": "کوچک کردن و قرینه‌سازی لبه‌های واژن بدون درد و بیهوشی"}, {"title": "واژینوپلاستی و پرینورافی", "slug": "vaginoplasty-perineorrhaphy", "desc": "تنگ کردن و ترمیم کانال و ورودی واژن پس از زایمان طبیعی"}, {"title": "سفید کردن واژن (وایتنینگ با لیزر)", "slug": "vaginal-whitening", "desc": "رفع تیرگی ناحیه بیکینی و کشاله ران با لیزر و کربوکسی‌تراپی"}, {"title": "تزریق ژل و چربی به لابیا ماژور", "slug": "labial-fat-filler-injection", "desc": "جوانسازی، حجم‌دهی و رفع آتروفی و چروکیدگی لابیای ماژور"}, {"title": "جوانسازی با لیزر مونالیزاتاچ و RF واژینال", "slug": "monalisa-touch-rf", "desc": "بهبود خشکی واژن، بی‌اختیاری خفیف ادرار و افزایش کلاژن‌سازی"}, {"title": "عمل هودکتومی کلیتوریس", "slug": "hoodectomy", "desc": "برداشتن پوست اضافه کلاهک کلیتوریس جهت زیبایی و ارگاسم بهتر"}]}, {"title": "بیماری‌ها و مشکلات بالینی زنان", "slug": "/gynecology/", "clusters": [{"title": "چکاپ دوره‌ای پاپ اسمیر و تست HPV", "slug": "pap-smear-hpv-checkup", "desc": "غربالگری سرطان دهانه رحم و تشخیص ژنوتیپ‌های پرخطر ویروس زگیل"}, {"title": "درمان عفونت‌های مقاوم واژینال و STD", "slug": "vaginal-infections-std", "desc": "کنترل عفونت‌های قارچی، باکتریایی، تبخال تناسلی و سوزاک"}, {"title": "اختلالات قاعدگی و منوراژی (خونریزی شدید)", "slug": "menstrual-disorders-menorrhagia", "desc": "علل پریودهای نامنظم، خونریزی غیرعادی و دردهای دیسمنوره"}, {"title": "سندرم تخمدان پلی‌کیستیک (PCOS)", "slug": "polycystic-ovary-pcos", "desc": "مدیریت تنبلی تخمدان، ریزش موی هورمونی و جوش‌های صورت"}, {"title": "مدیریت علائم یائسگی و هورمون‌درمانی (HRT)", "slug": "menopause-hrt-management", "desc": "کنترل گرگرفتگی، خشکی واژن و پیشگیری از پوکی استخوان"}, {"title": "تشخیص و درمان کیست تخمدان و آندومتریوز", "slug": "ovarian-cyst-endometriosis", "desc": "بررسی کیست‌های شکلاتی، چسبندگی‌های لگنی و دردهای لگنی"}]}, {"title": "جراحی‌های درمانی زنان و لاپاراسکوپی", "slug": "/therapeutic-surgeries/", "clusters": [{"title": "هیسترکتومی (برداشتن رحم به روش بسته)", "slug": "laparoscopic-hysterectomy", "desc": "جراحی برداشتن رحم در خونریزی غیرقابل کنترل و تومورها"}, {"title": "میومکتومی (برداشتن فیبروم با حفظ رحم)", "slug": "myomectomy-fibroids", "desc": "خارج کردن فیبروم‌های بزرگ رحمی با حفظ کامل قدرت باروری مادر"}, {"title": "جراحی افتادگی مثانه و رکتوسل (پرولاپس)", "slug": "cystocele-rectocele-repair", "desc": "ترمیم عضلات نگه‌دارنده احشای لگنی و رفع بی‌اختیاری ادرار"}, {"title": "لاپاراسکوپی و هیستروسکوپی تشخیصی-درمانی", "slug": "hysteroscopy-laparoscopy", "desc": "مشاهده داخل رحم بدون برش شکمی جهت رفع پولیپ و سپتوم"}]}, {"title": "خدمات درمان ناباروری و لقاح IVF", "slug": "/infertility-ivf/", "clusters": [{"title": "بررسی علل ناباروری و عکس رنگی رحم (HSG)", "slug": "infertility-evaluation-hsg", "desc": "بررسی باز بودن لوله‌ها، آزمایش اسپرموگرام و ذخیره تخمدان AMH"}, {"title": "لقاح آزمایشگاهی (IVF) و میکرواینجکشن (ICSI)", "slug": "ivf-icsi-treatment", "desc": "مراحل تحریک تخمک‌گذاری، پانکچر، لقاح جنین و انتقال به رحم"}, {"title": "تلقیح داخل رحمی اسپرم (روش IUI)", "slug": "iui-treatment", "desc": "تزریق مستقیم اسپرم شستشوشده به رحم در زمان تخمک‌گذاری"}, {"title": "تعیین جنسیت جنین (PGD) و فریز تخمک", "slug": "pgd-gender-selection-egg-freezing", "desc": "بررسی سلامت ژنتیکی جنین و حفظ باروری برای آینده"}]}]'::jsonb)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description;
INSERT INTO pezeshkan_pillars (name, short_name, slug, icon, count_badge, intent, dept, description, chips, branches)
VALUES ('قلب، عروق، دیابت و غدد', '["قلب و عروق", "دیابت و غدد"]'::jsonb, '/mag/cardio-endocrine/', 'cardio', '۳۰ خدمت تخصصی', 'پایش بیماری‌های متابولیک، غدد و پروسیجرهای اینترونشنال قلب', 'بخش کت‌لب آنژیوگرافی، کلینیک قلب و کلینیک غدد و دیابت', 'مدیریت دیابت، داروهای اوزمپیک، تیروئید، نوار قلب، اکو، آنژیوگرافی، استنت‌گذاری و آریتمی', '["دیابت و اوزمپیک", "کم‌کاری و ندول تیروئید", "اکوکاردیوگرافی داپلر", "تست ورزش و هولتر", "آنژیوگرافی و استنت", "باتری قلب پیس‌میکر"]'::jsonb, '[{"title": "فوق تخصص غدد درون‌ریز، دیابت و متابولیسم", "slug": "/endocrinology/", "clusters": [{"title": "تشخیص و مدیریت دیابت نوع ۱ و ۲ و بارداری", "slug": "diabetes-type1-type2-gestational", "desc": "تنظیم انسولین، داروهای نوین اوزمپیک، سنسور CGM و کنترل قند"}, {"title": "کم‌کاری و پرکاری تیروئید و ندول FNA", "slug": "thyroid-hypo-hyper-nodule", "desc": "تنظیم لووتیروکسین، نمونه‌برداری سوزنی FNA و سرطان تیروئید"}, {"title": "اختلالات رشد و کوتاهی قد کودکان", "slug": "growth-hormone-short-stature", "desc": "بررسی هورمون رشد و کنترل بلوغ زودرس یا دیررس نوجوانان"}, {"title": "بیماری‌های هیپوفیز و غده فوق کلیوی", "slug": "pituitary-adrenal-disorders", "desc": "سندرم کوشینگ، آدیسون، افزایش پرولاکتین و آدنوم هیپوفیز"}, {"title": "پوکی استخوان و مدیریت چاقی مدیکال", "slug": "osteoporosis-medical-weightloss", "desc": "تفسیر اسکن تراکم استخوان DEXA، درمان چربی خون و کاهش وزن دارویی"}]}, {"title": "خدمات تشخیصی غیرتهاجمی قلب در کلینیک", "slug": "/cardiology-diagnostics/", "clusters": [{"title": "نوار قلب (ECG) و اکوکاردیوگرافی داپلر", "slug": "ecg-echocardiography", "desc": "بررسی ریتم، سلامت دریچه‌های قلب و درصد کسر پمپاژ (EF)"}, {"title": "تست ورزش قلب (Treadmill Stress Test)", "slug": "treadmill-stress-test", "desc": "ارزیابی خون‌رسانی عروق کرونر در حین فعالیت فیزیکی شدید"}, {"title": "هولتر مانیتورینگ ریتم و فشار خون ۲۴ ساعته", "slug": "holter-ecg-blood-pressure", "desc": "ثبت آریتمی‌های پنهان، حملات تپش قلب و نوسانات فشار خون"}, {"title": "اکوکاردیوگرافی از راه مری (TEE)", "slug": "transesophageal-echo-tee", "desc": "تصویربرداری دقیق از پشت قلب برای بررسی عفونت دریچه و لخته"}]}, {"title": "خدمات اینترونشنال و کت‌لب بیمارستان", "slug": "/interventional-cardio/", "clusters": [{"title": "آنژیوگرافی عروق کرونر از دست و پا", "slug": "coronary-angiography", "desc": "تصویربرداری رنگی دقیق از تنگی‌ها و گرفتگی‌های عروق قلب"}, {"title": "آنژیوپلاستی و استنت‌گذاری (بالن و فنر)", "slug": "angioplasty-coronary-stent", "desc": "باز کردن انسداد شریان‌های قلب بدون نیاز به جراحی باز"}, {"title": "بستن سوراخ‌های مادرزادی قلب (ASD/VSD)", "slug": "congenital-asd-vsd-closure", "desc": "تعبیه چتر مسدودکننده سوراخ قلب با کاتتر بدون باز کردن قفسه سینه"}]}, {"title": "مدیریت آریتمی‌ها و الکتروفیزیولوژی قلب", "slug": "/electrophysiology/", "clusters": [{"title": "مطالعه الکتروفیزیولوژی و ابلیشن قلبی (EPS)", "slug": "eps-catheter-ablation", "desc": "نقشه‌برداری برق قلب و سوزاندن مسیرهای ایجادکننده تپش شدید"}, {"title": "تعبیه باتری قلب (پیس‌میکر) و دفیبریلاتور (ICD)", "slug": "pacemaker-icd-implantation", "desc": "کاشت ضربان‌ساز برای ضربان کند و شوک‌دهنده برای پیشگیری از ایست قلبی"}]}, {"title": "مدیریت بیماری‌های مزمن و توانبخشی قلب", "slug": "/chronic-care-rehab/", "clusters": [{"title": "درمان نارسایی احتقانی قلب و بحران فشار خون", "slug": "heart-failure-hypertension", "desc": "تنظیم داروهای تخصصی نارسایی و پیشگیری از سکته قلبی"}, {"title": "برنامه جامع بازتوانی قلبی (Cardiac Rehab)", "slug": "cardiac-rehabilitation", "desc": "تمرینات ورزشی و تغذیه‌ای تحت پایش پس از جراحی باز قلب یا سکته"}]}]'::jsonb)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description;
INSERT INTO pezeshkan_pillars (name, short_name, slug, icon, count_badge, intent, dept, description, chips, branches)
VALUES ('چکاپ، تفسیر آزمایش‌ها و تصویربرداری', '["آزمایشگاه جامع", "و تصویربرداری"]'::jsonb, '/mag/diagnostics/', 'diagnostics', '۴۲ خدمت تخصصی', 'تفسیر آزمایش خون، رزرو سونوگرافی، ام‌آر‌آی، سی‌تی اسکن و ماموگرافی', 'آزمایشگاه پاتوبیولوژی شبانه‌روزی و مرکز تصویربرداری پزشکی', 'تفسیر آنلاین آزمایش‌های خون، هورمون، ژنتیک NIPT، سونوگرافی داپلر، ام‌آر‌آی و PET-CT', '["تفسیر آزمایش خون CBC", "ام‌آر‌آی مغز و ستون فقرات", "سونوگرافی غربالگری آنومالی", "سی‌تی اسکن و سی‌تی آنژیو", "عکس رنگی رحم HSG", "پت اسکن PET-CT"]'::jsonb, '[{"title": "آزمایشگاه پاتوبیولوژی، بیوشیمی و هورمون", "slug": "/pathobiology-lab/", "clusters": [{"title": "پنل بیوشیمی، قند، چربی و آنزیم‌های کبد و کلیه", "slug": "biochemistry-liver-kidney", "desc": "بررسی FBS، A1C، کراتینین، اوره، SGOT، SGPT و چربی‌های خون"}, {"title": "پنل هورمونی تیروئید، بارداری و ویتامین‌ها", "slug": "hormones-thyroid-vitamins", "desc": "تفسیر TSH، Free T4، تیتراژ بتا، ویتامین D3 و ویتامین B12"}, {"title": "تومورمارکرهای غربالگری سرطان (PSA, CEA, CA-125)", "slug": "tumor-markers-screening", "desc": "غربالگری زودهنگام سرطان پروستات، تخمدان، پستان و گوارش"}, {"title": "آزمایش خون‌شناسی کامل (CBC) و تست‌های انعقادی", "slug": "cbc-coagulation-tests", "desc": "بررسی کم‌خونی، گلبول سفید، پلاکت و فاکتورهای PT، PTT و INR"}]}, {"title": "ژنتیک پزشکی، مولکولی و سیتولوژی", "slug": "/molecular-genetics/", "clusters": [{"title": "تست مولکولی زگیل تناسلی (HPV Genotyping)", "slug": "hpv-pcr-genotyping", "desc": "شناسایی سویه‌های پرخطر ۱۶ و ۱۸ و سویه‌های کم‌خطر ویروس زگیل"}, {"title": "غربالگری ژنتیکی سلامت جنین (آزمایش NIPT سل‌فری)", "slug": "nipt-cell-free-dna", "desc": "بررسی سندروم داون و ناهنجاری‌های کروموزومی از خون مادر"}, {"title": "پاتولوژی بیوپسی بافت و پاپ اسمیر مایع", "slug": "pathology-biopsy-liquid-pap", "desc": "بررسی خوش‌خیمی و بدخیمی توده‌های جراحی در آزمایشگاه پاتولوژی"}]}, {"title": "سونوگرافی و کالر داپلر تخصصی", "slug": "/ultrasound/", "clusters": [{"title": "سونوگرافی شکم، لگن، کلیه و مجاری ادراری", "slug": "abdominal-pelvic-ultrasound", "desc": "بررسی سنگ کلیه، کبد چرب، کیسه صفرا و مثانه"}, {"title": "سونوگرافی تخصصی بارداری (غربالگری NT و آنومالی)", "slug": "pregnancy-ultrasound-scans", "desc": "بررسی نقایص مادرزادی، اندازه اندام‌ها و سلامت جنین"}, {"title": "سونوگرافی نسج نرم پستان و تیروئید", "slug": "breast-thyroid-ultrasound", "desc": "تشخیص کیست و ندول‌های پستان و تیروئید بر اساس طبقه‌بندی TIRADS"}, {"title": "کالر داپلر عروقی (واریس پا و کاروتید گردن)", "slug": "vascular-color-doppler", "desc": "بررسی جریان خون عروق، لخته DVT و داپلر جفت جنین"}]}, {"title": "ام‌آر‌آی (MRI) و سی‌تی اسکن پیشرفته", "slug": "/mri-ct-scan/", "clusters": [{"title": "ام‌آر‌آی مغز، ستون فقرات و دیسک کمر", "slug": "brain-spine-mri", "desc": "تصویربرداری وضوح بالا از فتق دیسک، ام‌اس، سکته و تومورها"}, {"title": "ام‌آر‌آی مفاصل زانو و شانه (رباط و مینیسک)", "slug": "joint-msk-mri", "desc": "تشخیص دقیق پارگی رباط صلیبی، مینیسک و لابروم شانه"}, {"title": "سی‌تی اسکن ریه (HRCT) و مغز", "slug": "chest-brain-ct-scan", "desc": "تصویربرداری سریع از ریه، تروما، شکستگی‌ها و خونریزی مغزی"}, {"title": "سی‌تی آنژیوگرافی عروق کرونر قلب", "slug": "coronary-ct-angiography", "desc": "بررسی پلاک‌ها و گرفتگی‌های عروق قلب به روش غیرتهاجمی"}]}, {"title": "تصویربرداری تخصصی زنان، رادیوگرافی و تراکم استخوان", "slug": "/womens-imaging-xray/", "clusters": [{"title": "ماموگرافی دیجیتال غربالگری سرطان سینه", "slug": "digital-mammography", "desc": "عکس‌برداری با دوز پایین اشعه برای کشف توده‌های ریز پستان"}, {"title": "عکس رنگی رحم (HSG) با بیهوشی و بدون درد", "slug": "painless-hsg-xray", "desc": "بررسی باز بودن لوله‌های رحمی و چسبندگی در بانوان نابارور"}, {"title": "گرافی‌های دیجیتال ساده، OPG دندان و فک", "slug": "digital-xray-opg", "desc": "عکس دندان برای ایمپلنت و گرافی قفسه سینه و استخوان‌ها"}, {"title": "سنجش تراکم استخوان (DEXA Scan)", "slug": "dexa-bone-densitometry", "desc": "اندازه‌گیری مواد معدنی استخوان لگن و مهره‌ها برای پوکی استخوان"}]}, {"title": "پزشکی هسته‌ای و رادیولوژی مداخله‌ای", "slug": "/nuclear-interventional/", "clusters": [{"title": "اسکن هسته‌ای قلب، استخوان و تیروئید", "slug": "nuclear-scintigraphy", "desc": "بررسی خون‌رسانی عضله قلب، متاستاز استخوان و عملکرد تیروئید"}, {"title": "پت اسکن (PET-CT) مرحله‌بندی سرطان", "slug": "pet-ct-oncology-scan", "desc": "پیشرفته‌ترین متد تشخیص میزان پیشرفت و پاسخ به درمان تومورها"}, {"title": "بیوپسی و تخلیه کیست تحت هدایت سونوگرافی", "slug": "image-guided-biopsy", "desc": "نمونه‌برداری دقیق از توده‌های پستان، کبد و تیروئید بدون جراحی باز"}]}]'::jsonb)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description;
INSERT INTO pezeshkan_pillars (name, short_name, slug, icon, count_badge, intent, dept, description, chips, branches)
VALUES ('راهنمای علائم و تریاژ اورژانس', '["راهنمای علائم", "تریاژ اورژانس"]'::jsonb, '/mag/symptoms/', 'triage', '۲۸ راهنمای فوری', 'پاسخ به پرچم‌های قرمز و تریاژ اورژانس بیمارستان', 'تریاژ اورژانس شبانه‌روزی، پذیرش حاد و بخش مراقبت‌های ویژه', 'راهنمای علائم هشداردهنده (Red Flags)، سیستم تریاژ ESI و پنجره طلایی نجات جان بیمار', '["درد قفسه سینه", "زمان طلایی سکته مغزی FAST", "تنگی نفس حاد و آسم", "تروما و تصادفات", "مسمومیت دارویی", "سیستم تریاژ سطح ۱ تا ۵"]'::jsonb, '[{"title": "سیستم تریاژ ESI و اولویت‌بندی اورژانس", "slug": "/triage-esi/", "clusters": [{"title": "سطوح تریاژ ۱ تا ۵ بیمارستان (ESI)", "slug": "esi-triage-levels", "desc": "راهنمای اولویت‌بندی از احیای فوری و اورژانس تا درمانگاه سرپایی"}, {"title": "پرچم‌های قرمز دردهای ارجاعی قفسه سینه", "slug": "chest-pain-red-flags", "desc": "درد فشارنده جناغ منتشر به فک و دست چپ، عرق سرد و تنگی نفس"}]}, {"title": "اورژانس‌های قلبی، عروقی و فشار خون", "slug": "/cardiac-emergencies/", "clusters": [{"title": "سندرم حاد کرونری و سکته قلبی (MI)", "slug": "acute-coronary-syndrome-mi", "desc": "اقدامات طلایی اولیه، مصرف آسپرین و اعزام فوری با آمبولانس ۱۱۵"}, {"title": "بحران فشار خون و آریتمی‌های کشنده", "slug": "hypertensive-crisis-arrhythmias", "desc": "فشار خون بالای ۱۸ با سردرد شدید و تاری دید، تپش قلب بحرانی"}]}, {"title": "اورژانس‌های مغز، اعصاب و سکته", "slug": "/neuro-emergencies/", "clusters": [{"title": "سکته مغزی و پنجره طلایی معیار FAST", "slug": "stroke-fast-protocol-tpa", "desc": "افتادگی صورت، ضعف دست، اختلال گفتار و تزریق ترومبولیتیک TPA"}, {"title": "حملات تشنج مداوم و سردرد صاعقه‌ای", "slug": "status-epilepticus-thunderclap", "desc": "تشنج صرع بیش از ۵ دقیقه و سردرد ناگهانی شدید ناشی از خونریزی"}]}, {"title": "اورژانس‌های تنفسی، تروما و تصادفات", "slug": "/trauma-respiratory/", "clusters": [{"title": "نارسایی حاد تنفسی و آمبولی ریه (PE)", "slug": "acute-dyspnea-pulmonary-embolism", "desc": "درد قفسه سینه با تنفس عمیق، سرفه خونی و افت شدید اکسیژن خون"}, {"title": "پلی‌تروما، تصادفات و ترومای ستون فقرات", "slug": "polytrauma-spinal-cervical", "desc": "بی‌حرکت‌سازی گردن با کلار، کنترل خونریزی شدید و پیشگیری از شوک"}, {"title": "سوختگی‌های حاد و سوختگی استنشاقی", "slug": "burn-emergencies-inhalation", "desc": "محاسبه درصد سوختگی، پانسمان استریل و مایع‌درمانی وریدی"}]}, {"title": "مسمومیت‌ها، سم‌شناسی و پروسیجرهای بالین", "slug": "/toxicology-procedures/", "clusters": [{"title": "مسمومیت‌های دارویی، گاز CO و گزیدگی", "slug": "poisoning-co-gas-bites", "desc": "شستشوی معده، آنتی‌دوت‌ها، مونوکسید کربن، مارگزیدگی و عقرب‌زدگی"}, {"title": "احیای CPR، اینتوباسیون و سونوگرافی FAST", "slug": "cpr-fast-ultrasound-er", "desc": "ماساژ قلبی، شوک، لوله‌گذاری ریه و سونوگرافی کشف خونریزی پنهان شکم"}]}]'::jsonb)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description;
INSERT INTO pezeshkan_pillars (name, short_name, slug, icon, count_badge, intent, dept, description, chips, branches)
VALUES ('جراحی‌های چاقی و لاپاراسکوپی', '["جراحی چاقی", "و لاپاراسکوپی"]'::jsonb, '/mag/surgeries/', 'surgery', '۳۴ خدمت تخصصی', 'جراحی‌های لاپاراسکوپیک چاقی، فتق، کیسه صفرا، پستان و غدد', 'دپارتمان جراحی جنرال، کلینیک چاقی و اتاق عمل بیمارستان', 'اسلیو معده، بای‌پس کلاسیک و مینی، ترمیم فتق با مش، لاپاراسکوپی صفرا، جراحی پستان و تیروئید', '["اسلیو معده لاپاراسکوپی", "بای‌پس کلاسیک و مینی", "کیسه صفرا (کوله سیستکتومی)", "فتق کشاله ران با مش", "لامپکتومی و ماستکتومی", "جراحی تیروئید"]'::jsonb, '[{"title": "جراحی‌های چاقی و متابولیک (لاپاراسکوپی)", "slug": "/bariatric/", "clusters": [{"title": "عمل اسلیو معده لاپاراسکوپیک (Gastric Sleeve)", "slug": "laparoscopic-gastric-sleeve", "desc": "کوچک کردن حجم معده به شکل لوله با کاهش ۷۰ درصدی وزن اضافه"}, {"title": "بای‌پس کلاسیک و مینی بای‌پس معده", "slug": "gastric-bypass-omega-roux", "desc": "کاهش حجم معده و میانبر روده برای درمان همزمان دیابت و چاقی شدید"}, {"title": "جراحی ترکیبی ساسی بای‌پس (SASI)", "slug": "sasi-bypass-surgery", "desc": "تکنیک نوین ترکیب اسلیو و بای‌پس جهت حفظ مسیر طبیعی آندوسکوپی"}, {"title": "جراحی‌های اصلاحی چاقی (Revision Bariatric)", "slug": "revision-bariatric-surgery", "desc": "عمل مجدد برای بیمارانی که دچار بازگشت وزن یا عوارض شده‌اند"}]}, {"title": "جراحی‌های دستگاه گوارش و کیسه صفرا", "slug": "/gi-abdominal-surgery/", "clusters": [{"title": "کوله سیستکتومی لاپاراسکوپیک (برداشتن صفرا)", "slug": "laparoscopic-cholecystectomy", "desc": "برداشتن کیسه صفرا به دلیل سنگ یا پولیپ بدون برش بزرگ شکمی"}, {"title": "آپاندکتومی لاپاراسکوپی در فاز حاد", "slug": "laparoscopic-appendectomy", "desc": "برداشتن آپاندیس عفونی با ۳ سوراخ ریز پوستی و ترخیص یک‌روزه"}, {"title": "جراحی تومورهای روده (کولکتومی) و معده", "slug": "colectomy-gastrectomy-tumors", "desc": "برداشتن انکولوژیک بخش‌های درگیر روده و معده همراه غدد لنفاوی"}]}, {"title": "جراحی‌های انواع فتق با مش‌گذاری لاپاراسکوپیک", "slug": "/hernia-repair/", "clusters": [{"title": "فتق اینگوینال (کشاله ران) به روش TEP/TAPP", "slug": "laparoscopic-inguinal-hernia", "desc": "ترمیم بیرون‌زدگی احشا با توری مش به روش لاپاراسکوپیک بسته"}, {"title": "فتق نافی و فتق برشی شکم (Incisional)", "slug": "umbilical-incisional-hernia", "desc": "ترمیم فتق در محل ناف یا جای بخیه عمل‌های جراحی قبلی"}, {"title": "فتق هیاتال و جراحی فوندوپلیکاسیون نیسن", "slug": "hiatal-hernia-nissen-fundoplication", "desc": "جراحی لاپاراسکوپی برای درمان قطعی رفلاکس شدید اسید معده به مری"}]}, {"title": "جراحی‌های پستان و غدد درون‌ریز", "slug": "/breast-endocrine-surgery/", "clusters": [{"title": "برداشتن توده‌های خوش‌خیم فیبروآدنوم پستان", "slug": "breast-fibroadenoma-excision", "desc": "خارج کردن توده‌های خوش‌خیم سینه با حداقل اسکار جراحی"}, {"title": "لامپکتومی انکولوپلاستیک و ماستکتومی با بازسازی", "slug": "lumpectomy-mastectomy-reconstruction", "desc": "حفظ بافت طبیعی سینه یا تخلیه کامل همراه پروتز و پیوند همزمان"}, {"title": "تیروئیدکتومی جزئی و کامل با حفظ اعصاب حنجره", "slug": "thyroidectomy-vocal-nerve-preservation", "desc": "برداشتن تیروئید در گواتر و سرطان با پایش عصب صوتی"}]}, {"title": "جراحی‌های سرپایی بافت نرم و پوست", "slug": "/minor-outpatient-surgery/", "clusters": [{"title": "خارج کردن توده‌های چربی (لیپوم) و کیست سباسه", "slug": "lipoma-sebaceous-cyst-removal", "desc": "جراحی سرپایی توده‌های زیرپوستی با بی‌حسی موضعی در کلینیک"}, {"title": "جراحی ناخن فرورفته در گوشت (Ingrown Toenail)", "slug": "ingrown-toenail-surgery", "desc": "برداشتن دائمی ریشه ناخن عفونی جهت جلوگیری از عود مکرر"}, {"title": "دبریدمان تخصصی زخم پای دیابتی و زخم بستر", "slug": "diabetic-foot-ulcer-debridement", "desc": "پاکسازی بافت‌های مرده و پانسمان‌های نوین جهت جلوگیری از قطع عضو"}]}]'::jsonb)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description;
INSERT INTO pezeshkan_pillars (name, short_name, slug, icon, count_badge, intent, dept, description, chips, branches)
VALUES ('پوست، مو و زیبایی', '["پوست، مو", "و زیبایی پزشکی"]'::jsonb, '/mag/aesthetics-skin/', 'gi', '۳۶ خدمت تخصصی', 'تزریقات زیبایی، لیزر، جوانسازی، پیوند مو و بلفاروپلاستی', 'مرکز تخصصی پوست، لیزر درمانی و اتاق عمل کاشت مو', 'تزریق بوتاکس، فیلر لب روسی، هایفوتراپی، لیزر موهای زائد الکس، سابسیژن و کاشت موی Micro-FIT', '["تزریق بوتاکس و میگرن", "فیلر لب و کانتورینگ", "مزوژل پروفایلو و چربی", "هایفوتراپی و RF", "لیزر CO2 فرکشنال", "کاشت موی طبیعی FIT", "بلفاروپلاستی"]'::jsonb, '[{"title": "خدمات زیبایی و تزریقات پزشک متخصص", "slug": "/injectables/", "clusters": [{"title": "تزریق بوتاکس صورت، میگرن و تعریق زیر بغل", "slug": "botox-facial-migraine-hyperhidrosis", "desc": "رفع چین و چروک پیشانی، خط اخم، درمان میگرن و بوتاکس ماس‌تر فک"}, {"title": "تزریق فیلر و ژل لب روسی و کانتورینگ صورت", "slug": "dermal-fillers-lip-jawline", "desc": "حجم‌دهی لب، اصلاح فرم بینی، زاویه‌سازی چانه، گونه و فیلر زیر چشم"}, {"title": "مزوژل‌های جوانساز پروفایلو (Profhilo) و جالوپرو", "slug": "profhilo-jalupro-skinboosters", "desc": "آبرسانی عمقی، تحریک کلاژن‌سازی و لیفت طبیعی افتادگی پوست"}, {"title": "تزریق چربی و نانوفت به صورت و دست", "slug": "fat-transfer-nanofat", "desc": "حجم‌دهی ماندگار با سلول‌های بنیادی چربی بدن فرد"}, {"title": "لیفت صورت و ابرو با نخ‌های خاردار PDO و COG", "slug": "pdo-cog-thread-lift", "desc": "کشیدن پوست صورت، گردن و غبغب بدون جراحی باز"}, {"title": "مزوتراپی و پی‌آر‌پی (PRP) پوست و مو", "slug": "mesotherapy-prp-hair-face", "desc": "کوکتل‌های تقویتی و پلاسمای خون برای توقف ریزش مو و شفافیت پوست"}]}, {"title": "خدمات پیشرفته دستگاهی و لیزر", "slug": "/lasers-devices/", "clusters": [{"title": "لیزر موهای زائد الکساندرایت، دایود و Nd:YAG", "slug": "laser-hair-removal-alex-diode", "desc": "حذف دائمی موهای زائد با طول موج‌های متناسب با تایپ پوستی"}, {"title": "هایفوتراپی دابلو و اولترافورمر (HIFU)", "slug": "hifu-skin-tightening", "desc": "لیفت غیرجراحی لایه SMAS صورت و رفع غبغب در ۱ جلسه"}, {"title": "آر اف فرکشنال سوزنی (اسکارلت و ویواچه)", "slug": "fractional-rf-microneedling", "desc": "سفت کردن پوست، بستن منافذ باز و بهبود جای جوش"}, {"title": "لیزر CO2 فرکشنال لایه‌برداری و اسکار آکنه", "slug": "fractional-co2-laser", "desc": "درمان اسکارهای فرورفته، ترک‌های پوستی و جوانسازی کلاژن"}, {"title": "پاک کردن تتو با کیوسوئیچ و لیزر عروقی واریس", "slug": "q-switch-tattoo-vascular-laser", "desc": "حذف رنگدانه‌های تتو، کک‌ومک و درمان قرمزی روزاسه و واریس سطحی"}]}, {"title": "مراقبت‌های بالینی و پاکسازی پوست (فیشیال)", "slug": "/clinical-skincare/", "clusters": [{"title": "فیشیال تخصصی کلینیکال و هیدرافیشیال", "slug": "clinical-facial-hydrafacial", "desc": "پاکسازی عمقی منافذ، لایه‌برداری، تخلیه کومدون و آبرسانی پوست"}, {"title": "میکرونیدلینگ و میکرودرم ابریژن لایه‌بردار", "slug": "microneedling-microdermabrasion", "desc": "تحریک کلاژن‌سازی طبیعی برای رفع لک و کدری پوست"}, {"title": "سابسیژن با کانولا برای جای جوش عمیق", "slug": "subcision-acne-scars", "desc": "آزادسازی بافت‌های فیبروتیک زیرین پوست و ترکیب با تزریق ژل"}]}, {"title": "بیماری‌های پوست، مو و ناخن (درماتولوژی)", "slug": "/clinical-dermatology/", "clusters": [{"title": "تشخیص و درمان ریزش موی آندروژنیک و سکه‌ای", "slug": "androgenetic-alopecia-areata", "desc": "بررسی هورمونی، داروهای ماینوکسیدیل و فیناستراید و مزوتراپی"}, {"title": "پروتکل درمان آکنه فعال و تجویز راکوتان", "slug": "acne-vulgaris-isotretinoin", "desc": "درمان ریشه‌ای جوش‌های التهابی و پایش آنزیم‌های کبد"}, {"title": "کنترل پسوریازیس، اگزما و ویتیلیگو (پیسی)", "slug": "psoriasis-eczema-vitiligo", "desc": "مدیریت بیماری‌های التهابی خودایمنی با داروهای بیولوژیک و موضعی"}, {"title": "کرایوتراپی زگیل‌های تناسلی و جراحی خال‌ها", "slug": "cryotherapy-genital-warts-moles", "desc": "فریز زگیل با نیتروژن مایع و برداشتن نمونه‌های مشکوک پوستی"}]}, {"title": "کاشت موی طبیعی و جراحی پلک (بلفاروپلاستی)", "slug": "/hair-transplant-blepharo/", "clusters": [{"title": "کاشت موی طبیعی به روش Micro-FIT و SUT", "slug": "micro-fit-hair-transplant", "desc": "پیوند مو با حداکثر تراکم، خط رویش طبیعی بدون بیهوشی و جراحی"}, {"title": "کاشت طبیعی ابرو با زاویه خواب مناسب مو", "slug": "eyebrow-transplant", "desc": "طراحی فرم دلخواه ابرو با موهای ظریف پشت سر بدون ریزش"}, {"title": "بلفاروپلاستی سرپایی پلک بالا و پایین", "slug": "upper-lower-blepharoplasty", "desc": "برداشتن پوست و چربی اضافه پلک و جوانسازی فرم چشم‌ها"}]}]'::jsonb)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description;
INSERT INTO pezeshkan_pillars (name, short_name, slug, icon, count_badge, intent, dept, description, chips, branches)
VALUES ('گوارش، کبد و نشیمنگاه (پروکتولوژی)', '["گوارش و کبد", "لیزر نشیمنگاه"]'::jsonb, '/mag/proctology-gi/', 'pharmacy', '۳۵ خدمت تخصصی', 'درمان سرپایی با لیزر نشیمنگاه، آندوسکوپی، کولونوسکوپی و کبد', 'کلینیک کولورکتال و لیزر نشیمنگاه، مرکز آندوسکوپی و کبد', 'لیزر هموروئید، شقاق، فیستول، کیست مویی، آندوسکوپی با بیهوشی، کولونوسکوپی و درمان کبد چرب', '["لیزر هموروئید (بواسیر)", "درمان شقاق با لیزر و بوتاکس", "فیستول مقعدی", "کیست مویی پایین کمر", "کولونوسکوپی غربالگری", "کبد چرب گرید ۱ تا ۳"]'::jsonb, '[{"title": "پروسیجرهای آندوسکوپی و تشخیصی-درمانی", "slug": "/endoscopy-interventions/", "clusters": [{"title": "آندوسکوپی فوقانی دستگاه گوارش با بیهوشی ملایم", "slug": "upper-gi-endoscopy", "desc": "مشاهده مستقیم مری، معده و اثنی‌عشر جهت کشف زخم و هلیکوباکتر"}, {"title": "کولونوسکوپی کامل و پولیپ‌کتومی روده", "slug": "colonoscopy-polypectomy", "desc": "غربالگری سرطان روده، برداشتن پولیپ‌ها و بررسی خونریزی مقعدی"}, {"title": "ای‌آر‌سی‌پی (ERCP) سنگ مجرای صفراوی", "slug": "ercp-biliary-stones", "desc": "خارج کردن سنگ صفرا و باز کردن تنگی مجرا بدون باز کردن شکم"}, {"title": "فیبرواسکن کبد (FibroScan) بدون نمونه‌برداری", "slug": "liver-fibroscan", "desc": "سونوگرافی پیشرفته تعیین شدت فیبروز و گرید کبد چرب"}]}, {"title": "بیماری‌های مری، معده و روده (داخلی)", "slug": "/upper-lower-gi/", "clusters": [{"title": "ریفلاکس اسید معده (GERD) و مری بارت", "slug": "gerd-barretts-esophagus", "desc": "سوزش سر دل، سرفه ناشی از اسید و تغییرات پیش‌سرطانی مخاط"}, {"title": "زخم معده و اثنی‌عشر و ریشه‌کنی میکروب معده", "slug": "peptic-ulcer-helicobacter", "desc": "درمان هلیکوباکتر پیلوری با آنتی‌بیوتیک و داروهای کاهنده اسید"}, {"title": "سندرم روده تحریک‌پذیر (IBS) و رژیم فودمپ", "slug": "irritable-bowel-syndrome-ibs", "desc": "مدیریت دردهای شکمی، نفخ شدید، اسهال و یبوست با اصلاح تغذیه"}, {"title": "بیماری‌های التهابی روده (کرون و کولیت اولسراتیو)", "slug": "crohns-ulcerative-colitis-ibd", "desc": "کنترل التهاب مزمن روده با داروهای بیولوژیک و مهارکننده ایمنی"}]}, {"title": "بیماری‌های کبد، مجاری صفراوی و پانکراس", "slug": "/hepatology/", "clusters": [{"title": "کبد چرب (NAFLD) گرید ۱، ۲ و ۳", "slug": "fatty-liver-grades", "desc": "اصلاح سبک زندگی، داروهای نوین و پیشگیری از پیشرفت به سمت سیروز"}, {"title": "هپاتیت‌های ویروسی B و C و خودایمنی", "slug": "viral-hepatitis-b-c", "desc": "درمان‌های ضدویروسی خوراکی نوین با اثربخشی قطعی بالای ۹۵٪"}, {"title": "سیروز کبد، آسیت (آب آوردن شکم) و پانکراتیت", "slug": "cirrhosis-ascites-pancreatitis", "desc": "مدیریت نارسایی کبد و التهاب حاد و مزمن لوزالمعده"}]}, {"title": "پروکتولوژی و جراحی‌های لیزری نشیمنگاه", "slug": "/proctology-laser/", "clusters": [{"title": "لیزر هموروئید (بواسیر داخلی و خارجی)", "slug": "laser-hemorrhoid-surgery", "desc": "درمان سرپایی با لیزر دیود پرتوان بدون بیهوشی، بخیه و خونریزی"}, {"title": "درمان شقاق مقعدی (فیشر) با لیزر و بوتاکس", "slug": "anal-fissure-laser-botox", "desc": "ترمیم زخم دردناک مقعد و شل‌کردن عضله اسفنکتر بدون بی‌اختیاری"}, {"title": "جراحی فیستول مقعدی با لیزر فیستولوتومی", "slug": "anal-fistula-laser-seton", "desc": "تخلیه مجرای چرکی مزمن با لیزر فیبر نوری بدون آسیب به عضله"}, {"title": "کیست مویی پایین کمر (سینوس پیلونیدال) با لیزر", "slug": "pilonidal-sinus-laser", "desc": "تخلیه و سوزاندن ریشه کیست با لیزر و دوران نقاهت ۲ روزه"}, {"title": "تخلیه آبسه مقعدی و درمان زگیل مقعدی با لیزر", "slug": "perianal-abscess-laser-warts", "desc": "جراحی اورژانسی چرک مقعد و سوزاندن زگیل‌های داخل و اطراف مقعد"}]}]'::jsonb)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description;
INSERT INTO pezeshkan_pillars (name, short_name, slug, icon, count_badge, intent, dept, description, chips, branches)
VALUES ('دانشنامه و اطلاعات دارویی', '["دانشنامه داروها", "عوارض و تداخلات"]'::jsonb, '/mag/drugs/', 'pediatrics', '۵۰+ رده دارویی', 'اطلاعاتی تخصصی (دوز، عوارض، تداخلات و نحوه مصرف صحیح داروها)', 'سامانه اطلاعات و مشاوره دارویی آنلاین بیمارستان پزشکآن', 'دایرکتوری جامع داروها بر اساس طبقه‌بندی درمانی: مسکن‌ها، داروهای گوارش، قلب، اعصاب، دیابت و آنتی‌بیوتیک‌ها', '["مسکن‌ها و NSAID", "امپرازول و ضداسید معده", "داروهای فشار خون و استاتین", "ضدافسردگی SSRI", "آنتی‌بیوتیک‌ها", "متفورمین و اوزمپیک"]'::jsonb, '[{"title": "مسکن‌ها، داروهای ضددرد و ضدالتهاب", "slug": "/analgesics-antiinflammatory/", "clusters": [{"title": "مسکن‌های ضدالتهاب غیرکورتونی (NSAIDs)", "slug": "nsaids-ibuprofen-naproxen", "desc": "ایبوپروفن، ناپروکسن، دیکلوفناک، سلکوکسیب و خطرات گوارشی آن‌ها"}, {"title": "مسکن‌های غیرمخدر (استامینوفن) و مخدرها", "slug": "acetaminophen-opioid-analgesics", "desc": "استامینوفن ساده، کدئین، ترامادول و اصول مصرف ایمن بدون وابستگی"}, {"title": "کورتیکواستروئیدها (کورتون‌ها) و شل‌کننده‌ها", "slug": "corticosteroids-muscle-relaxants", "desc": "دگزامتازون، پردنیزولون، متوکاربامول و باکلوفن در اسپاسم عضلانی"}]}, {"title": "داروهای گوارشی و ترشح اسید معده", "slug": "/gastrointestinal-drugs/", "clusters": [{"title": "کاهنده‌های اسید معده PPI (امپرازول و پانتوپرازول)", "slug": "ppi-omeprazole-pantoprazole", "desc": "نحوه مصرف ناشتا، عوارض بلندمدت و تفاوت فاموتیدین با مهارکننده‌ها"}, {"title": "ملین‌ها، ضداسهال‌ها و ضدتهوع‌ها (دمیترون)", "slug": "laxatives-antidiarrheal-ondansetron", "desc": "پیدرولاکس، بیزاکودیل، لوپرامید، اوندانسترون و شربت‌های آنتی‌اسید"}, {"title": "داروهای تنظیم‌کننده اسپاسم روده (IBS)", "slug": "ibs-antispasmodics-mebeverine", "desc": "مبورین، کلیدینیوم سی و پروبیوتیک‌ها در سندرم روده تحریک‌پذیر"}]}, {"title": "داروهای قلب، عروق و فشار خون", "slug": "/cardiovascular-drugs/", "clusters": [{"title": "داروهای فشار خون (بتابلاکرها و مهارکننده ACE)", "slug": "antihypertensive-drugs", "desc": "متوپرولول، پروپرانولول، لوزارتان، انالاپریل و آملودیپین"}, {"title": "داروهای چربی خون (استاتین‌ها) و دیورتیک‌ها", "slug": "statins-atorvastatin-diuretics", "desc": "آتورواستاتین، روزوواستاتین، لازیکس (فروزماید) و اسپیرونولاکتون"}, {"title": "داروهای ضدانعقاد و رقیق‌کننده خون", "slug": "anticoagulants-aspirin-warfarin", "desc": "آسپرین، پلاویکس، وارفارین و پایش آزمایش PT-INR جهت پیشگیری از سکته"}]}, {"title": "داروهای اعصاب، روان‌پزشکی و میگرن", "slug": "/cns-psychiatry-drugs/", "clusters": [{"title": "داروهای ضدافسردگی SSRI (سرترالین و فلوکستین)", "slug": "ssri-sertraline-fluoxetine", "desc": "عوارض اولیه، زمان اثربخشی، سندرم قطع ناگهانی و تنظیم دوز"}, {"title": "داروهای ضداضطراب و خواب‌آور (آلپرازولام و زولپیدم)", "slug": "anxiolytics-alprazolam-zolpidem", "desc": "کلونازپام، دیازپام، لورازپام، ملاتونین و خطرات سوءمصرف داروها"}, {"title": "داروهای ضدتشنج، دردهای عصبی و میگرن", "slug": "anticonvulsants-gabapentin-sumatriptan", "desc": "گاباپنتین، پرگابالین، سدیم والپروات و سوماتریپتان در حملات سردرد"}]}, {"title": "آنتی‌بیوتیک‌ها و داروهای ضدمیکروبی", "slug": "/anti-infectives/", "clusters": [{"title": "آنتی‌بیوتیک‌ها (چرک‌خشک‌کن‌ها) و مقاومت دارویی", "slug": "antibiotics-amoxicillin-cefixime", "desc": "آموکسی‌سیلین، سفیکسیم، آزیترومایسین، سیپروفلوکساسین و تکمیل دوره درمان"}, {"title": "داروهای ضدویروس، ضدقارچ و ضدانگل", "slug": "antiviral-antifungal-drugs", "desc": "آسیکلوویر در تبخال، فلوکونازول در عفونت قارچی و قرص مترونیدازول"}]}, {"title": "داروهای غدد، هورمونی و دیابت", "slug": "/endocrine-hormonal-drugs/", "clusters": [{"title": "داروهای دیابت و آمپول‌های لاغری (متفورمین و اوزمپیک)", "slug": "diabetes-metformin-ozempic", "desc": "سماگلوتاید، انسولین‌های قلمی لانتوس و نوورپید و افت قند خون"}, {"title": "داروهای تیروئید و هورمون‌های زنان (لووتیروکسین و ال‌دی)", "slug": "levothyroxine-contraceptives", "desc": "نحوه مصرف ناشتا تیروئید و قرص‌های پیشگیری از بارداری روکین و دوفاستون"}]}, {"title": "داروهای تنفسی، پوستی و بیولوژیک", "slug": "/respiratory-dermatology-biologics/", "clusters": [{"title": "اسپری‌های تنفسی آسم و آنتی‌هیستامین‌ها", "slug": "inhalers-salbutamol-antihistamines", "desc": "اسپری سالبوتامول، سیمبیکورت، سیتریزین، لوراتادین و شربت سرفه"}, {"title": "داروهای جوش راکوتان و ضدریزش ماینوکسیدیل", "slug": "isotretinoin-minoxidil-finasteride", "desc": "ایزوترتینوئین خوراکی، محلول ماینوکسیدیل و قرص فیناستراید"}, {"title": "داروهای بیولوژیک و شیمی‌درمانی (سینورا و آلتبرل)", "slug": "biologics-cinnoRA-chemotherapy", "desc": "درمان روماتیسم، ام‌اس، پسوریازیس و کنترل تومورهای بدخیم"}]}]'::jsonb)
