INSERT INTO pezeshkan_articles (title, slug, summary, raw_html, content_html, image, image_alt, pillar_id, category_name, category_icon, doctor_id, author, read_time, last_reviewed, tag, tag_class, status, meta_title, meta_description, focus_keyword, faqs, schema_type, old_slugs, schema_data, custom_schema_json)
VALUES ('راهنمای بالینی درمان غیرجراحی دیسک کمر و سیاتیک: از شاک‌ویو تا لیزر پرتوان', 'nonsurgical-treatments-lumbar-disc-sciatica', 'بررسی علمی راهکارهای نوین توانبخشی و مداخله‌ای بدون نیاز به بیهوشی و تیغ جراحی، همراه با معیارهای تریاژ اورژانس سندرم دم اسب.', '<p dir="rtl" style="direction: rtl; unicode-bidi: isolate; text-align: right;"><br></p><p data-path-to-node="1" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">در این نسخه، تمام جزئیات فایل‌های پایگاه دانش شما (از آناتومی محتوای سئوشده ۲۰۲۶، استراتژی کلمات کلیدی و فرمول TF-IDF گرفته تا انسان‌نویسی، قواعد بولت‌پوینت‌گذاری، فرمول‌های اپتیکی و استاندارد صفحات محصول) به صورت یکپارچه و با لحنی کاملاً حرفه‌ای برای ارائه به کارفرما تدوین شده است:</p><h2 dir="rtl" style="direction: rtl; unicode-bidi: isolate; text-align: right;">شیوه‌نامه جامع سئو محتوا، مهندسی مقالات علمی و ویراستاری وب‌سایت «آسمان شب» (استاندارد ۲۰۲۶)</h2><p data-path-to-node="4" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="4" data-index-in-node="0">تهیه‌کننده:</b> واحد استراتژی محتوا و سئو</p><p data-path-to-node="5" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="5" data-index-in-node="0">مخاطب:</b> مدیریت محترم مؤسسۀ آسمان شب (telescope.ir)</p><p data-path-to-node="6" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="6" data-index-in-node="0">موضوع:</b> تدوین چهارچوب استاندارد برای نگارش و سئو مقالات تخصصی و صفحات محصول با هدف تثبیت مرجعیت علمی (Authority) و کسب رتبه‌های برتر در موتورهای جست‌وجو</p><h2 data-path-to-node="8" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">مقدمه و هدف استراتژیک</h2><p data-path-to-node="9" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">وب‌سایت «آسمان شب» یک فروشگاه اینترنتی معمولی نیست؛ بلکه مرجع تخصصی تجهیزات نجومی و اپتیکی (تلسکوپ، دوربین دوچشمی، میکروسکوپ و لوازم جانبی) در ایران است. در سال ۲۰۲۶، موتور جست‌وجوی گوگل از یک «سیستم تطبیق کلمات» به یک «ماشین پاسخ‌گوی هوشمند (Answer Engine)» مجهز به هوش مصنوعی تبدیل شده است. در این فضا، محتوای سطحی، ترجمه‌های ماشینی یا متن‌های پر شده از کلمات تکراری نه‌تنها رتبه‌ای کسب نمی‌کنند، بلکه اعتبار دامنه را به خطر می‌اندازند.</p><p data-path-to-node="10" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">فرمول موفقیت سئو محتوا در سال ۲۰۲۶ یک اصل کلیدی دارد: <b data-path-to-node="10" data-index-in-node="54">«برای انسان بنویسید و برای ربات‌های موتور جست‌وجو ساختاربندی کنید.»</b> هدف این شیوه‌نامه، ایجاد یک خط‌کش دقیق و مهندسی‌شده برای تیم محتوا است تا هر مقاله یا صفحۀ محصولی که در سایت تولید می‌شود، از نظر <b data-path-to-node="10" data-index-in-node="252">عمق علمی (فیزیک اپتیک)</b>، <b data-path-to-node="10" data-index-in-node="276">ساختار سئو داخلی (On-Page SEO)</b> و <b data-path-to-node="10" data-index-in-node="309">ویراستاری صوری</b> در بالاترین سطح استاندارد جهانی قرار گیرد.</p><figure class="editorial-figure align-center" contenteditable="false" draggable="true">
          <img src="/mag/uploads/2026/10/11_1792235748_d87d26a0.webp" alt="تصویر شاخص" class="editorial-body-image">
          
        </figure><p data-path-to-node="10" dir="rtl" style="text-align: right;">
        </p><h2 style="direction: rtl; unicode-bidi: isolate; text-align: right;" dir="rtl"><span style="font-family: Vazirmatn, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, sans-serif; font-size: 21px; font-weight: 800;">بخش اول: استراتژی تحقیق کلمات کلیدی و بهینه‌سازی معنایی (Semantic SEO)</span></h2><p data-path-to-node="13" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">در الگوریتم‌های پردازش زبان طبیعی گوگل (مانند BERT و MUM)، تکرار طوطی‌وار کلمۀ کلیدی (Keyword Stuffing) نه‌تنها منسوخ شده، بلکه منجر به جریمۀ سایت می‌شود. استراتژی کلمات کلیدی در «آسمان شب» بر سه ستون زیر استوار است:</p><h3 data-path-to-node="14" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">۱. تفکیک «مترادف‌ها» از «موجودیت‌ها و مفاهیم مرتبط (Entities / LSI)»</h3><p data-path-to-node="15" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">نویسندگان باید تفاوت میان کلمات هم‌معنی و موجودیت‌های علمی حوزه اپتیک را در نگارش لحاظ کنند:</p><ul data-path-to-node="16" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="16,0,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="16,0,0" data-index-in-node="0">کلمات مترادف (Synonyms):</b> عباراتی که دقیقاً یک مفهوم را می‌رسانند (مانند: خرید تلسکوپ، قیمت تلسکوپ، فروش تلسکوپ).</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="16,1,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="16,1,0" data-index-in-node="0">موجودیت‌ها و کلمات مرتبط معنایی (Entities / LSI):</b> مفاهیم و اجزای تخصصی که حضور آن‌ها در متن به گوگل اثبات می‌کند مقاله توسط یک متخصص اپتیک نوشته شده است. برای مثال، در مقاله‌ای دربارۀ «دوربین دوچشمی»، عباراتی نظیر <i data-path-to-node="16,1,0" data-index-in-node="214">منشور جانبی (Porro)، منشور مستقیم (Roof)، شیشۀ کراون باریوم (BaK-4)، اندود چندلایه و کامل (FMC)، مردمک خروجی، فاصلۀ آسودگی چشم، ضریب تاریک-روشنی و تنظیم دیوپتر</i> موجودیت‌های ضروری هستند.</p></li></ul><h3 data-path-to-node="17" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">۲. قانون طلایی پراکندگی کلمۀ کلیدی اصلی و منطق آماری TF-IDF</h3><p data-path-to-node="18" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">کلمۀ کلیدی اصلی مقاله باید دقیقاً در ۷ نقطۀ استراتژیک زیر قرار گیرد:</p><ol start="1" data-path-to-node="19" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="19,0,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="19,0,0" data-index-in-node="0">عنوان سئو (Meta Title):</b> ترجیحاً در ابتدای عنوان.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="19,1,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="19,1,0" data-index-in-node="0">آدرس صفحه (URL):</b> کوتاه، گویا و حاوی کلمۀ کلیدی.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="19,2,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="19,2,0" data-index-in-node="0">عنوان اصلی مقاله (تگ H1):</b> تنها یک تگ H1 در هر صفحه مجاز است.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="19,3,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="19,3,0" data-index-in-node="0">پاراگراف اول:</b> به صورت کاملاً طبیعی در ۱۰۰ کلمۀ ابتدایی متن.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="19,4,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="19,4,0" data-index-in-node="0">توضیحات متا (Meta Description):</b> جهت افزایش نرخ کلیک (CTR) در نتایج جست‌وجو.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="19,5,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="19,5,0" data-index-in-node="0">زیرتیترها:</b> حضور در حداقل یکی از هدینگ‌های <code data-path-to-node="19,5,0" data-index-in-node="42">H2</code>.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="19,6,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="19,6,0" data-index-in-node="0">متن جایگزین تصویر (Alt Text):</b> در مرتبط‌ترین تصویر شاخص مقاله.</p></li></ol><ul data-path-to-node="20" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="20,0,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="20,0,0" data-index-in-node="0">توزیع طبیعی بر اساس فرمول TF-IDF:</b> بر اساس منطق آماری <span class="math-inline" data-math="TF = \frac{n}{N}" data-index-in-node="53">$TF = \frac{n}{N}$</span> (که در آن <span class="math-inline" data-math="n" data-index-in-node="80">$n$</span> تعداد تکرار یک مفهوم خاص و <span class="math-inline" data-math="N" data-index-in-node="109">$N$</span> کل کلمات مقاله است)، موجودیت‌ها و اصطلاحات تخصصی نباید در یک پاراگراف انباشته شوند، بلکه باید به صورت کاملاً طبیعی و همگن در سراسر طول مقاله پخش گردند.</p></li></ul><h3 data-path-to-node="21" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">۳. چهار روش استاندارد استخراج مفاهیم پیش از نگارش</h3><p data-path-to-node="22" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">تیم نویسندگان موظف است پیش از شروع نگارش هر مقاله، مفاهیم و تیترهای خود را از ۴ منبع زیر استخراج کند:</p><ol start="1" data-path-to-node="23" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="23,0,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">بررسی بخش <b data-path-to-node="23,0,0" data-index-in-node="10">جست‌وجوهای مرتبط (Related Searches)</b> و کلمات پررنگ‌شده (Bold) در توضیحات متای رقبا در صفحۀ اول گوگل.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="23,1,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="23,1,0" data-index-in-node="0">مهندسی معکوس ۳ لینک اول گوگل</b> جهت استخراج اصطلاحات تخصصی، نام قطعات و دغدغه‌های پوشش داده شده.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="23,2,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">استخراج سؤالات بخش <b data-path-to-node="23,2,0" data-index-in-node="19">People Also Ask (PAA)</b> و تبدیل ۴ تا ۵ سؤال پرتکرار به زیرتیترهای <code data-path-to-node="23,2,0" data-index-in-node="83">H2</code> یا <code data-path-to-node="23,2,0" data-index-in-node="89">H3</code>.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="23,3,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">بهینه‌سازی برای <b data-path-to-node="23,3,0" data-index-in-node="16">جست‌وجوی صوتی (Voice Search)</b> با گنجاندن عبارات سؤالی و طولانی (چطور، چگونه، چرا، چه تفاوتی دارد) در ساختار تیترها و بخش سؤالات متداول (FAQ).</p></li></ol><h2 data-path-to-node="25" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">بخش دوم: آناتومی محتوای سئوشده و بهینه‌سازی برای هوش مصنوعی گوگل (SGE)</h2><h3 data-path-to-node="26" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">۱. رفع سریع نیاز کاربر (Search Intent) و تکنیک «پاسخ مستقیم در صدر»</h3><p data-path-to-node="27" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">گوگل در سال ۲۰۲۶ به کمک هوش مصنوعی خود (AI Overviews)، مقالات را اسکن کرده و خلاصۀ پاسخ را در بالای نتایج نمایش می‌دهد. برای تصاحب این جایگاه (رتبۀ صفر):</p><ul data-path-to-node="28" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="28,0,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="28,0,0" data-index-in-node="0">ممنوعیت مقدمه‌های کلیشه‌ای:</b> شروع مقاله با جملات بدیهی و بی‌ارزش (مانند: «از دیرباز انسان به آسمان شب علاقه داشته است...») مطلقاً ممنوع است.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="28,1,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="28,1,0" data-index-in-node="0">پاسخ مستقیم در ۱۰۰ کلمۀ اول (Direct Answer on Top):</b> پاراگراف اول باید شامل یک <b data-path-to-node="28,1,0" data-index-in-node="78">قلاب (Hook)</b> درگیرکننده باشد و در همان ۵ ثانیۀ اول، بدون حاشیه‌پردازی، مستقیماً به سؤال یا نیاز اصلی کاربر پاسخ دهد.</p></li></ul><h3 data-path-to-node="29" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">۲. پیاده‌سازی عمیق استانداردهای E-E-A-T در حوزۀ اپتیک و نجوم</h3><p data-path-to-node="30" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">گوگل کیفیت محتوا را با چهار معیار <b data-path-to-node="30" data-index-in-node="34">تجربه (Experience)</b>، <b data-path-to-node="30" data-index-in-node="54">تخصص (Expertise)</b>، <b data-path-to-node="30" data-index-in-node="72">اعتبار (Authoritativeness)</b> و <b data-path-to-node="30" data-index-in-node="101">اعتماد (Trustworthiness)</b> می‌سنجد. در «آسمان شب»، اجرای این اصول به شکل زیر الزامی است:</p><ul data-path-to-node="31" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="31,0,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="31,0,0" data-index-in-node="0">صداقت ذاتی و علمی (قانون عدم ادعا):</b> لحن مقالات باید ۱۰۰٪ علمی، بی‌طرفانه، قاطع و آموزشی باشد. استفاده از واژگان تبلیغاتی زرد و اغراق‌آمیز (مانند: «معجزۀ اپتیک»، «فوق‌العاده‌ترین تلسکوپ جهان») ممنوع است. همچنین نویسنده نباید مستقیماً در متن ادعا کند که «این محتوا صادقانه است»؛ بلکه صداقت و اعتماد باید از دل فکت‌های فیزیکی (مثلاً بیان صادقانۀ وجود خطای رنگی در تلسکوپ‌های شکستی آکروماتیک، یا خطای گیسو در تلسکوپ‌های نیوتونی با نسبت کانونی پایین، یا وزن بالای دوچشمی‌های منشور جانبی) به مخاطب منتقل شود.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="31,1,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="31,1,0" data-index-in-node="0">کالبدشکافی فیزیکی و اپتیکی (اثبات تخصص):</b> هیچ ویژگی فنی نباید به صورت سطحی بیان شود. هر ادعای اپتیکی باید در ۳ الی ۴ پاراگراف از منظر فیزیک نور تشریح گردد. (مثال: هنگام بررسی «فاصلۀ کانونی کم در برابر فاصلۀ کانونی زیاد در قطر دهانۀ یکسان»، باید تأثیر آن بر انحنای آینه یا قطر عدسی، میزان شکست نور، اندازۀ تصویر، روشنایی تصویر در عکاسی، عمق میدان، خطای انحنای میدان و توان تفکیک به طور کامل کالبدشکافی شود).</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="31,2,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="31,2,0" data-index-in-node="0">مثال‌های رصدی و کاربردی ملموس (اثبات تجربه):</b> مفاهیم تئوری باید با مثال‌های عملی رصد آسمان یا طبیعت‌گردی همراه شوند. به جای جملۀ کلی «این ابزار کیفیت بالایی دارد»، باید تشریح شود که این کیفیت در رصد «اقمار مشتری، هلال زهره، شکاف کاسینی در حلقه‌های زحل یا سحابی جبار»، بررسی وضعیت «قرص ایری (Airy Disk)» از ۱ تا ۱۰ برای سنجش دید نجومی، یا در دوربین‌های دوچشمی برای «مشاهدۀ جزئیات پرهای پرنده و بال پروانه در فاصلۀ ۴/۵ تا ۵ متری (فوکوس نزدیک)» و «رصد پرستوی دریایی روی قایق پرتلاطم» چگونه عمل می‌کند.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="31,3,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="31,3,0" data-index-in-node="0">بسط فرمول‌های محاسباتی اپتیک:</b> در مقالات جامع آموزشی و راهنمای خرید، نویسنده موظف است فرمول‌های استاندارد پایگاه دانش را مطرح کرده و حتماً با یک <b data-path-to-node="31,3,0" data-index-in-node="144">مثال عددی واقعی</b> حل کند:</p><ul data-path-to-node="31,3,1" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="31,3,1,0,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="31,3,1,0,0" data-index-in-node="0">بزرگ‌نمایی تلسکوپ:</b> <span class="math-inline" data-math="M = F_o / F_e" data-index-in-node="19">$M = F_o / F_e$</span> (تقسیم فاصلۀ کانونی شیئی بر چشمی) و <b data-path-to-node="31,3,1,0,0" data-index-in-node="69">بیشینۀ بزرگ‌نمایی مفید:</b> ۲ برابر قطر دهانه به میلی‌متر.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="31,3,1,1,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="31,3,1,1,0" data-index-in-node="0">نسبت کانونی:</b> <span class="math-inline" data-math="f = F / D" data-index-in-node="13">$f = F / D$</span> و مقایسۀ سرعت دو ابزار از طریق فرمول <span class="math-inline" data-math="L_1 / L_2 = (f_2 / f_1)^2" data-index-in-node="60">$L_1 / L_2 = (f_2 / f_1)^2$</span>.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="31,3,1,2,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="31,3,1,2,0" data-index-in-node="0">مردمک خروجی (Exit Pupil):</b> در دوچشمی از تقسیم قطر دهانه بر بزرگ‌نمایی، و در تلسکوپ از تقسیم فاصلۀ کانونی چشمی بر نسبت کانونی تلسکوپ (با تأکید بر محدودیت ۷ میلی‌متری مردمک چشم انسان در تاریکی).</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="31,3,1,3,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="31,3,1,3,0" data-index-in-node="0">توان گردآوری نور:</b> <span class="math-inline" data-math="W = (D / 6)^2" data-index-in-node="18">$W = (D / 6)^2$</span> نسبت به چشم انسان و مقایسۀ دو ابزار با مجذور نسبت قطر دهانه‌ها.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="31,3,1,4,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="31,3,1,4,0" data-index-in-node="0">میدان دید:</b> رابطۀ میدان دید واقعی و ظاهری (<span class="math-inline" data-math="TFOV = AFOV / M" data-index-in-node="42">$TFOV = AFOV / M$</span>) و تبدیل میدان دید زاویه‌ای به میدان دید خطی در ۱۰۰۰ متر با ضریب ۱۷/۴۵ (یا ۱۷/۵).</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="31,3,1,5,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="31,3,1,5,0" data-index-in-node="0">توان تفکیک و حد قدر:</b> فرمول‌های حد ریلی (<span class="math-inline" data-math="5.5 / D_{\text{inch}}" data-index-in-node="40">$5.5 / D_{\text{inch}}$</span>)، حد داوز (<span class="math-inline" data-math="4.56 / D_{\text{inch}}" data-index-in-node="73">$4.56 / D_{\text{inch}}$</span>)، فرمول توان تفکیک در نور مرئی (<span class="math-inline" data-math="125 / D" data-index-in-node="128">$125 / D$</span>) و فرمول حد قدر (<span class="math-inline" data-math="5 \times \log_{10}(D_{\text{cm}}) + 7.5" data-index-in-node="153">$5 \times \log_{10}(D_{\text{cm}}) + 7.5$</span>).</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="31,3,1,6,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="31,3,1,6,0" data-index-in-node="0">فرمول‌های تخصصی دوچشمی و میکروسکوپ:</b> ضریب تاریک-روشنی (<span class="math-inline" data-math="\sqrt{M \times D}" data-index-in-node="54">$\sqrt{M \times D}$</span>) در دوچشمی‌ها، و فرمول حد تفکیک میکروسکوپ (<span class="math-inline" data-math="R = \frac{0.61 \lambda}{N.A}" data-index-in-node="115">$R = \frac{0.61 \lambda}{N.A}$</span>) و ضریب گشادگی (<span class="math-inline" data-math="N.A = n \cdot \sin\alpha" data-index-in-node="160">$N.A = n \cdot \sin\alpha$</span>) به همراه تحلیل تفاوت عدسی‌های شیئی خشک و ایمرسیون روغنی.</p></li></ul></li></ul><h3 data-path-to-node="32" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">۳. معماری خوشه‌های محتوایی (Topic Clusters) و لینک‌سازی داخلی</h3><p data-path-to-node="33" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">یک مقالۀ تنها برای مرجع شدن کافی نیست. محتوای سایت باید در قالب خوشه‌های موضوعی سازمان‌دهی شود:</p><ul data-path-to-node="34" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="34,0,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="34,0,0" data-index-in-node="0">مقالات ستون فقرات (Pillar Pages):</b> مقالات جامع و مرجع (بالای ۲۰۰۰ تا ۳۰۰۰ کلمه) که یک موضوع اصلی را به صورت ۳۶۰ درجه پوشش می‌دهند.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="34,1,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="34,1,0" data-index-in-node="0">مقالات خوشه‌ای (Clusters):</b> مقالات تخصصی فرعی که هر کدام یک جنبۀ خاص (مثلاً «مقایسۀ چشمی هویگنس و رامزدن» یا «تأثیر کندانسور و دیافراگم آیریس در کنتراست میکروسکوپ») را بررسی می‌کنند.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="34,2,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="34,2,0" data-index-in-node="0">لینک‌سازی داخلی استراتژیک:</b> ارتباط میان مقالات پایلار، کلاستر و صفحات محصول باید با <b data-path-to-node="34,2,0" data-index-in-node="83">انکرتکست‌های (Anchor Text) دقیق و توصیفی</b> انجام شود. استفاده از عبارات مبهم مانند «اینجا کلیک کنید» ممنوع است.</p></li></ul><h2 data-path-to-node="36" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">بخش سوم: معماری نگارش، خوانایی (Readability) و انسان‌نویسی (Humanizing)</h2><p data-path-to-node="37" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">طبق ماتریس لحن، حوزۀ فعالیت «آسمان شب» ترکیبی از <b data-path-to-node="37" data-index-in-node="49">تکنولوژی و دانش علمی</b> است؛ بنابراین لحن محتوا باید <b data-path-to-node="37" data-index-in-node="99">«آموزشی، دقیق، قاطع، علمی و بدون حاشیه»</b> باشد و در عین حال، از نظر ساختاری ۱۰۰٪ انسانی و خوانا نگارش شود:</p><h3 data-path-to-node="38" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">۱. قوانین انسان‌نویسی و حذف الگوهای رباتی (Anti-AI Patterns)</h3><ol start="1" data-path-to-node="39" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="39,0,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="39,0,0" data-index-in-node="0">خط قرمز واژگان رباتی:</b> استفاده از عبارات کلیشه‌ای و ماشینی نظیر <i data-path-to-node="39,0,0" data-index-in-node="63">«بی‌شک»، «در دنیای پرشتاب امروزی»، «حائز اهمیت است»، «شایان ذکر است»، «علاوه بر این»</i> و <i data-path-to-node="39,0,0" data-index-in-node="150">«در نهایت باید گفت»</i> در مقالات آسمان شب اکیداً ممنوع است.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="39,1,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="39,1,0" data-index-in-node="0">شکستن ریتم مکانیکی (Burstiness):</b> پاراگراف‌ها و جملات نباید هم‌اندازه و یکنواخت باشند. نویسنده باید ریتم طبیعی کلام را با الگوی ترکیبی حفظ کند: <b data-path-to-node="39,1,0" data-index-in-node="143">[یک جملۀ کوتاه و کوبندۀ علمی] + [یک جملۀ متوسط] + [یک جملۀ طولانی و تشریحی همراه با مثال رصدی یا آزمایشگاهی]</b>.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="39,2,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="39,2,0" data-index-in-node="0">انسجام و جریان متن (Flow):</b> انتقال از یک زیرتیتر به زیرتیتر بعدی باید کاملاً منطقی و نرم باشد تا رشتۀ کلام از دست خواننده خارج نشود.</p></li></ol><h3 data-path-to-node="40" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">۲. مهندسی اسکن‌پذیری (Scannability) و چیدمان بصری</h3><p data-path-to-node="41" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">از آنجا که کاربران وب متن را اسکن می‌کنند و دیوارهای طولانی متن (Wall of Text) باعث افزایش نرخ پرش (Bounce Rate) می‌شوند، رعایت قواعد زیر الزامی است:</p><ul data-path-to-node="42" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="42,0,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="42,0,0" data-index-in-node="0">قانون ۳ خط در پاراگراف:</b> هیچ پاراگرافی نباید در نمای موبایل بیش از ۳ الی ۴ خط باشد. هر پاراگراف باید تنها حول یک ایدۀ واحد بچرخد.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="42,1,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="42,1,0" data-index-in-node="0">سلسله‌مراتب منطقی هدینگ‌ها (H1 تا H4):</b> ساختار تیترها نقشۀ راه ربات گوگل و چشم کاربر است. استفاده از <code data-path-to-node="42,1,0" data-index-in-node="100">H3</code> بدون وجود <code data-path-to-node="42,1,0" data-index-in-node="113">H2</code> قبلی ممنوع است. هدینگ‌ها باید توصیفی و جذاب باشند (مثلاً به جای تیتر مبهم «نکات مهم»، نوشته شود: «۷ ویژگی کلیدی در انتخاب دوربین دوچشمی نجومی»).</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="42,2,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="42,2,0" data-index-in-node="0">استاندارد بولت‌پوینت‌گذاری (Bullet Points):</b></p><ul data-path-to-node="42,2,1" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="42,2,1,0,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">در مقالات بالای ۵۰۰ کلمه حداقل ۱ تا ۲ لیست، و در مقالات جامع بالای ۲۰۰۰ کلمه وجود <b data-path-to-node="42,2,1,0,0" data-index-in-node="82">۳ تا ۵ لیست</b> الزامی است.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="42,2,1,1,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">برای موارد غیرترتیبی (مثل ویژگی‌های دوچشمی شکاری) از <b data-path-to-node="42,2,1,1,0" data-index-in-node="53">لیست نقطه‌ای</b> و برای مراحل ترتیبی (مثل مراحل هم‌خط‌سازی آینه‌های تلسکوپ نیوتونی یا تنظیم شاریوت میکروسکوپ) از <b data-path-to-node="42,2,1,1,0" data-index-in-node="162">لیست شماره‌دار</b> استفاده شود.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="42,2,1,2,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="42,2,1,2,0" data-index-in-node="0">طول بهینۀ هر لیست بین ۳ تا ۷ آیتم است.</b> لیست‌های ۲ آیتمی باید در قالب جمله نوشته شوند و لیست‌های بیش از ۱۰ آیتم باید با زیرعنوان‌های <code data-path-to-node="42,2,1,2,0" data-index-in-node="132">H3</code> به دسته‌های کوچک‌تر تقسیم گردند.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="42,2,1,3,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><i data-path-to-node="42,2,1,3,0" data-index-in-node="0">قانون عدم افراط:</i> لیست‌ها مکمل پاراگراف‌ها هستند نه جایگزین آن‌ها؛ مقاله‌ای که تماماً بولت‌پوینت باشد، ساختار علمی و روایی خود را از دست می‌دهد.</p></li></ul></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="42,3,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="42,3,0" data-index-in-node="0">جداول مقایسه‌ای و تحلیل پس از جدول:</b> برای مقایسۀ مشخصات فنی (مانند مقایسۀ منشور جانبی Porro و مستقیم Roof، یا مقایسۀ ضریب گشادگی <span class="math-inline" data-math="N.A" data-index-in-node="128">$N.A$</span> و حد تفکیک در عدسی‌های شیئی آکروماتیک، فلوریت و آپوکروماتیک با بزرگ‌نمایی‌های ۴، ۱۰، ۴۰ و ۱۰۰ برابر) استفاده از جدول الزامی است. <b data-path-to-node="42,3,0" data-index-in-node="261">قانون قطعی:</b> بلافاصله پس از هر جدول، نویسنده موظف است ۲ تا ۳ پاراگراف مفصل در تحلیل داده‌های جدول و نتیجه‌گیری عملی برای راهنمایی خریدار بنویسد.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="42,4,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="42,4,0" data-index-in-node="0">برجسته‌سازی هدفمند (Bold):</b> بولد کردن کل یک جمله ممنوع است؛ تنها مفاهیم کلیدی و اصطلاحات مهم در هر پاراگراف باید پررنگ شوند.</p></li></ul><h2 data-path-to-node="44" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">بخش چهارم: شیوه‌نامۀ اختصاصی واژگان اپتیکی و ویراستاری صوری «آسمان شب»</h2><p data-path-to-node="45" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">تمامی محتواهای متنی وب‌سایت باید از نظر واژگان تخصصی و نگارش صوری، ۱۰۰٪ یکدست و منطبق بر استانداردهای مصوب مؤسسه باشند:</p><h3 data-path-to-node="46" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">۱. الزام استفاده از واژه‌نامۀ مصوب اپتیکی</h3><p data-path-to-node="47" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">نویسندگان حق استفاده از ترجمه‌های سلیقه‌ای را ندارند و باید منحصراً از معادل‌های فارسی مصوب «آسمان شب» استفاده کنند:</p><ul data-path-to-node="48" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,0,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,0,0" data-index-in-node="0">Aperture:</b> گشودگی دهانه / روزنه</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,1,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,1,0" data-index-in-node="0">Optical Tube:</b> لولۀ اپتیکی / راستۀ نور</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,2,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,2,0" data-index-in-node="0">Finder Scope:</b> جوینده (و <code data-path-to-node="48,2,0" data-index-in-node="24">Red-dot finder</code>: جویندۀ نقطه‌قرمز)</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,3,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,3,0" data-index-in-node="0">Eyepiece / Ocular:</b> چشمی (و <code data-path-to-node="48,3,0" data-index-in-node="27">Eyepiece Holder</code>: جاچشمی)</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,4,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,4,0" data-index-in-node="0">Objective:</b> عدسی شیئی</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,5,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,5,0" data-index-in-node="0">Exit Pupil:</b> مردمک خروجی</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,6,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,6,0" data-index-in-node="0">Eye Relief:</b> فاصلۀ آسودگی چشم</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,7,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,7,0" data-index-in-node="0">Focal Ratio:</b> نسبت کانونی</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,8,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,8,0" data-index-in-node="0">Focal Reducer:</b> کانون‌کاه</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,9,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,9,0" data-index-in-node="0">Collimation:</b> هم‌خط‌سازی (و <code data-path-to-node="48,9,0" data-index-in-node="27">Collimator</code>: هم‌خط‌ساز)</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,10,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,10,0" data-index-in-node="0">Mount:</b> مقر (<code data-path-to-node="48,10,0" data-index-in-node="12">Alt-Az Mount</code>: استقرار سمتی-ارتفاعی / <code data-path-to-node="48,10,0" data-index-in-node="49">Equatorial</code>: استوایی)</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,11,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,11,0" data-index-in-node="0">GoTo:</b> جرم‌یاب خودکار</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,12,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,12,0" data-index-in-node="0">Guide Scope:</b> گایداسکوپ (تلسکوپ راهنما)</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,13,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,13,0" data-index-in-node="0">Diagonal:</b> چپقی (<code data-path-to-node="48,13,0" data-index-in-node="16">Mirror diagonal</code>: چپقی آینه‌ای / <code data-path-to-node="48,13,0" data-index-in-node="48">Prism Diagonal</code>: چپقی منشوری)</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,14,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,14,0" data-index-in-node="0">Coating:</b> اندود / پوشينه (مانند: «اندود چندلایه و کامل» برای <code data-path-to-node="48,14,0" data-index-in-node="60">FMC</code>)</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,15,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,15,0" data-index-in-node="0">Correcting Plate:</b> تیغۀ تصحیح</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,16,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,16,0" data-index-in-node="0">Dovetail bar:</b> رابط یا صفحۀ اتصال دم‌چلچله‌ای</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,17,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,17,0" data-index-in-node="0">Baffle:</b> موج‌گیر</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,18,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,18,0" data-index-in-node="0">Backlash:</b> لقّی</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,19,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,19,0" data-index-in-node="0">Seeing:</b> دید نجومی (و <code data-path-to-node="48,19,0" data-index-in-node="21">Scintillation</code>: سوسوزنی)</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,20,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,20,0" data-index-in-node="0">Twilight Factor:</b> ضریب تاریک-روشنی</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,21,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,21,0" data-index-in-node="0">Near Focus:</b> فوکوس نزدیک (نزدیک‌ترین فاصلۀ فوکوس)</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,22,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,22,0" data-index-in-node="0">Interpupillary Distance:</b> بازۀ بین دو مردمک چشمی</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,23,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,23,0" data-index-in-node="0">Revolver (در میکروسکوپ):</b> صفحۀ گردان (قطعۀ دماغی چرخنده)</p></li></ul><h3 data-path-to-node="49" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">۲. قانون نگارش نام برندها و واژگان لاتین</h3><ul data-path-to-node="50" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="50,0,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">تا جای ممکن باید از نگارش واژه‌ها و حروف لاتین در میان متن فارسی پرهیز شود.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="50,1,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="50,1,0" data-index-in-node="0">قانون اولیه‌نگاری:</b> نام برندها، کمپانی‌ها یا ساختارهای خاص، <b data-path-to-node="50,1,0" data-index-in-node="59">تنها در اولین مرتبه</b> در متن به صورت «تلفظ فارسی + (نام انگلیسی در پرانتز)» درج می‌شوند؛ مانند: «اسکای‌واچر (Sky-Watcher)»، «سلسترون (Celestron)» یا «منشور جانبی (Porro)». در تمامی دفعات بعدی در طول همان متن، <b data-path-to-node="50,1,0" data-index-in-node="266">صرفاً تلفظ فارسی</b> (اسکای‌واچر، سلسترون، منشور جانبی) بدون حروف لاتین نوشته می‌شود.</p></li></ul><h3 data-path-to-node="51" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">۳. قوانین ویرایش صوری (مبتنی بر شیوه‌نامۀ علی آزادگان)</h3><p data-path-to-node="1" dir="rtl" style="text-align: right;"></p><ol start="1" data-path-to-node="52" dir="rtl"><li dir="rtl" style="text-align: right;"><p data-path-to-node="52,0,0" dir="rtl" style="text-align: right;"><b data-path-to-node="52,0,0" data-index-in-node="0">رعایت دقیق نیم‌فاصله (<code data-path-to-node="52,0,0" data-index-in-node="22">Ctrl+Shift+2</code>):</b> در تمامی پسوندهای جمع («ها» مانند: تلسکوپ‌ها، چشمی‌ها)، پیشوندهای افعال («می» و «نمی» مانند: می‌چرخد، نمی‌تواند)، صفت‌های تفضیلی و عالی («تر» و «ترین» مانند: شفاف‌تر، بزرگ‌ترین) و واژگان مرکب (مانند: بزرگ‌نمایی، پرنده‌نگری، هم‌خط‌سازی، سه‌پایه) رعایت نیم‌فاصله الزامی است.</p></li></ol>', '<p dir="rtl" style="direction: rtl; unicode-bidi: isolate; text-align: right;"><br></p><p data-path-to-node="1" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">در این نسخه، تمام جزئیات فایل‌های پایگاه دانش شما (از آناتومی محتوای سئوشده ۲۰۲۶، استراتژی کلمات کلیدی و فرمول TF-IDF گرفته تا انسان‌نویسی، قواعد بولت‌پوینت‌گذاری، فرمول‌های اپتیکی و استاندارد صفحات محصول) به صورت یکپارچه و با لحنی کاملاً حرفه‌ای برای ارائه به کارفرما تدوین شده است:</p><h2 dir="rtl" style="direction: rtl; unicode-bidi: isolate; text-align: right;">شیوه‌نامه جامع سئو محتوا، مهندسی مقالات علمی و ویراستاری وب‌سایت «آسمان شب» (استاندارد ۲۰۲۶)</h2><p data-path-to-node="4" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="4" data-index-in-node="0">تهیه‌کننده:</b> واحد استراتژی محتوا و سئو</p><p data-path-to-node="5" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="5" data-index-in-node="0">مخاطب:</b> مدیریت محترم مؤسسۀ آسمان شب (telescope.ir)</p><p data-path-to-node="6" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="6" data-index-in-node="0">موضوع:</b> تدوین چهارچوب استاندارد برای نگارش و سئو مقالات تخصصی و صفحات محصول با هدف تثبیت مرجعیت علمی (Authority) و کسب رتبه‌های برتر در موتورهای جست‌وجو</p><h2 data-path-to-node="8" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">مقدمه و هدف استراتژیک</h2><p data-path-to-node="9" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">وب‌سایت «آسمان شب» یک فروشگاه اینترنتی معمولی نیست؛ بلکه مرجع تخصصی تجهیزات نجومی و اپتیکی (تلسکوپ، دوربین دوچشمی، میکروسکوپ و لوازم جانبی) در ایران است. در سال ۲۰۲۶، موتور جست‌وجوی گوگل از یک «سیستم تطبیق کلمات» به یک «ماشین پاسخ‌گوی هوشمند (Answer Engine)» مجهز به هوش مصنوعی تبدیل شده است. در این فضا، محتوای سطحی، ترجمه‌های ماشینی یا متن‌های پر شده از کلمات تکراری نه‌تنها رتبه‌ای کسب نمی‌کنند، بلکه اعتبار دامنه را به خطر می‌اندازند.</p><p data-path-to-node="10" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">فرمول موفقیت سئو محتوا در سال ۲۰۲۶ یک اصل کلیدی دارد: <b data-path-to-node="10" data-index-in-node="54">«برای انسان بنویسید و برای ربات‌های موتور جست‌وجو ساختاربندی کنید.»</b> هدف این شیوه‌نامه، ایجاد یک خط‌کش دقیق و مهندسی‌شده برای تیم محتوا است تا هر مقاله یا صفحۀ محصولی که در سایت تولید می‌شود، از نظر <b data-path-to-node="10" data-index-in-node="252">عمق علمی (فیزیک اپتیک)</b>، <b data-path-to-node="10" data-index-in-node="276">ساختار سئو داخلی (On-Page SEO)</b> و <b data-path-to-node="10" data-index-in-node="309">ویراستاری صوری</b> در بالاترین سطح استاندارد جهانی قرار گیرد.</p><figure class="editorial-figure align-center" contenteditable="false" draggable="true">
          <img src="/mag/uploads/2026/10/11_1792235748_d87d26a0.webp" alt="تصویر شاخص" class="editorial-body-image">
          
        </figure><p data-path-to-node="10" dir="rtl" style="text-align: right;">
        </p><h2 style="direction: rtl; unicode-bidi: isolate; text-align: right;" dir="rtl"><span style="font-family: Vazirmatn, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, sans-serif; font-size: 21px; font-weight: 800;">بخش اول: استراتژی تحقیق کلمات کلیدی و بهینه‌سازی معنایی (Semantic SEO)</span></h2><p data-path-to-node="13" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">در الگوریتم‌های پردازش زبان طبیعی گوگل (مانند BERT و MUM)، تکرار طوطی‌وار کلمۀ کلیدی (Keyword Stuffing) نه‌تنها منسوخ شده، بلکه منجر به جریمۀ سایت می‌شود. استراتژی کلمات کلیدی در «آسمان شب» بر سه ستون زیر استوار است:</p><h3 data-path-to-node="14" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">۱. تفکیک «مترادف‌ها» از «موجودیت‌ها و مفاهیم مرتبط (Entities / LSI)»</h3><p data-path-to-node="15" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">نویسندگان باید تفاوت میان کلمات هم‌معنی و موجودیت‌های علمی حوزه اپتیک را در نگارش لحاظ کنند:</p><ul data-path-to-node="16" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="16,0,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="16,0,0" data-index-in-node="0">کلمات مترادف (Synonyms):</b> عباراتی که دقیقاً یک مفهوم را می‌رسانند (مانند: خرید تلسکوپ، قیمت تلسکوپ، فروش تلسکوپ).</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="16,1,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="16,1,0" data-index-in-node="0">موجودیت‌ها و کلمات مرتبط معنایی (Entities / LSI):</b> مفاهیم و اجزای تخصصی که حضور آن‌ها در متن به گوگل اثبات می‌کند مقاله توسط یک متخصص اپتیک نوشته شده است. برای مثال، در مقاله‌ای دربارۀ «دوربین دوچشمی»، عباراتی نظیر <i data-path-to-node="16,1,0" data-index-in-node="214">منشور جانبی (Porro)، منشور مستقیم (Roof)، شیشۀ کراون باریوم (BaK-4)، اندود چندلایه و کامل (FMC)، مردمک خروجی، فاصلۀ آسودگی چشم، ضریب تاریک-روشنی و تنظیم دیوپتر</i> موجودیت‌های ضروری هستند.</p></li></ul><h3 data-path-to-node="17" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">۲. قانون طلایی پراکندگی کلمۀ کلیدی اصلی و منطق آماری TF-IDF</h3><p data-path-to-node="18" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">کلمۀ کلیدی اصلی مقاله باید دقیقاً در ۷ نقطۀ استراتژیک زیر قرار گیرد:</p><ol start="1" data-path-to-node="19" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="19,0,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="19,0,0" data-index-in-node="0">عنوان سئو (Meta Title):</b> ترجیحاً در ابتدای عنوان.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="19,1,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="19,1,0" data-index-in-node="0">آدرس صفحه (URL):</b> کوتاه، گویا و حاوی کلمۀ کلیدی.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="19,2,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="19,2,0" data-index-in-node="0">عنوان اصلی مقاله (تگ H1):</b> تنها یک تگ H1 در هر صفحه مجاز است.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="19,3,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="19,3,0" data-index-in-node="0">پاراگراف اول:</b> به صورت کاملاً طبیعی در ۱۰۰ کلمۀ ابتدایی متن.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="19,4,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="19,4,0" data-index-in-node="0">توضیحات متا (Meta Description):</b> جهت افزایش نرخ کلیک (CTR) در نتایج جست‌وجو.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="19,5,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="19,5,0" data-index-in-node="0">زیرتیترها:</b> حضور در حداقل یکی از هدینگ‌های <code data-path-to-node="19,5,0" data-index-in-node="42">H2</code>.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="19,6,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="19,6,0" data-index-in-node="0">متن جایگزین تصویر (Alt Text):</b> در مرتبط‌ترین تصویر شاخص مقاله.</p></li></ol><ul data-path-to-node="20" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="20,0,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="20,0,0" data-index-in-node="0">توزیع طبیعی بر اساس فرمول TF-IDF:</b> بر اساس منطق آماری <span class="math-inline" data-math="TF = \frac{n}{N}" data-index-in-node="53">$TF = \frac{n}{N}$</span> (که در آن <span class="math-inline" data-math="n" data-index-in-node="80">$n$</span> تعداد تکرار یک مفهوم خاص و <span class="math-inline" data-math="N" data-index-in-node="109">$N$</span> کل کلمات مقاله است)، موجودیت‌ها و اصطلاحات تخصصی نباید در یک پاراگراف انباشته شوند، بلکه باید به صورت کاملاً طبیعی و همگن در سراسر طول مقاله پخش گردند.</p></li></ul><h3 data-path-to-node="21" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">۳. چهار روش استاندارد استخراج مفاهیم پیش از نگارش</h3><p data-path-to-node="22" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">تیم نویسندگان موظف است پیش از شروع نگارش هر مقاله، مفاهیم و تیترهای خود را از ۴ منبع زیر استخراج کند:</p><ol start="1" data-path-to-node="23" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="23,0,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">بررسی بخش <b data-path-to-node="23,0,0" data-index-in-node="10">جست‌وجوهای مرتبط (Related Searches)</b> و کلمات پررنگ‌شده (Bold) در توضیحات متای رقبا در صفحۀ اول گوگل.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="23,1,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="23,1,0" data-index-in-node="0">مهندسی معکوس ۳ لینک اول گوگل</b> جهت استخراج اصطلاحات تخصصی، نام قطعات و دغدغه‌های پوشش داده شده.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="23,2,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">استخراج سؤالات بخش <b data-path-to-node="23,2,0" data-index-in-node="19">People Also Ask (PAA)</b> و تبدیل ۴ تا ۵ سؤال پرتکرار به زیرتیترهای <code data-path-to-node="23,2,0" data-index-in-node="83">H2</code> یا <code data-path-to-node="23,2,0" data-index-in-node="89">H3</code>.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="23,3,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">بهینه‌سازی برای <b data-path-to-node="23,3,0" data-index-in-node="16">جست‌وجوی صوتی (Voice Search)</b> با گنجاندن عبارات سؤالی و طولانی (چطور، چگونه، چرا، چه تفاوتی دارد) در ساختار تیترها و بخش سؤالات متداول (FAQ).</p></li></ol><h2 data-path-to-node="25" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">بخش دوم: آناتومی محتوای سئوشده و بهینه‌سازی برای هوش مصنوعی گوگل (SGE)</h2><h3 data-path-to-node="26" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">۱. رفع سریع نیاز کاربر (Search Intent) و تکنیک «پاسخ مستقیم در صدر»</h3><p data-path-to-node="27" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">گوگل در سال ۲۰۲۶ به کمک هوش مصنوعی خود (AI Overviews)، مقالات را اسکن کرده و خلاصۀ پاسخ را در بالای نتایج نمایش می‌دهد. برای تصاحب این جایگاه (رتبۀ صفر):</p><ul data-path-to-node="28" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="28,0,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="28,0,0" data-index-in-node="0">ممنوعیت مقدمه‌های کلیشه‌ای:</b> شروع مقاله با جملات بدیهی و بی‌ارزش (مانند: «از دیرباز انسان به آسمان شب علاقه داشته است...») مطلقاً ممنوع است.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="28,1,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="28,1,0" data-index-in-node="0">پاسخ مستقیم در ۱۰۰ کلمۀ اول (Direct Answer on Top):</b> پاراگراف اول باید شامل یک <b data-path-to-node="28,1,0" data-index-in-node="78">قلاب (Hook)</b> درگیرکننده باشد و در همان ۵ ثانیۀ اول، بدون حاشیه‌پردازی، مستقیماً به سؤال یا نیاز اصلی کاربر پاسخ دهد.</p></li></ul><h3 data-path-to-node="29" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">۲. پیاده‌سازی عمیق استانداردهای E-E-A-T در حوزۀ اپتیک و نجوم</h3><p data-path-to-node="30" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">گوگل کیفیت محتوا را با چهار معیار <b data-path-to-node="30" data-index-in-node="34">تجربه (Experience)</b>، <b data-path-to-node="30" data-index-in-node="54">تخصص (Expertise)</b>، <b data-path-to-node="30" data-index-in-node="72">اعتبار (Authoritativeness)</b> و <b data-path-to-node="30" data-index-in-node="101">اعتماد (Trustworthiness)</b> می‌سنجد. در «آسمان شب»، اجرای این اصول به شکل زیر الزامی است:</p><ul data-path-to-node="31" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="31,0,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="31,0,0" data-index-in-node="0">صداقت ذاتی و علمی (قانون عدم ادعا):</b> لحن مقالات باید ۱۰۰٪ علمی، بی‌طرفانه، قاطع و آموزشی باشد. استفاده از واژگان تبلیغاتی زرد و اغراق‌آمیز (مانند: «معجزۀ اپتیک»، «فوق‌العاده‌ترین تلسکوپ جهان») ممنوع است. همچنین نویسنده نباید مستقیماً در متن ادعا کند که «این محتوا صادقانه است»؛ بلکه صداقت و اعتماد باید از دل فکت‌های فیزیکی (مثلاً بیان صادقانۀ وجود خطای رنگی در تلسکوپ‌های شکستی آکروماتیک، یا خطای گیسو در تلسکوپ‌های نیوتونی با نسبت کانونی پایین، یا وزن بالای دوچشمی‌های منشور جانبی) به مخاطب منتقل شود.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="31,1,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="31,1,0" data-index-in-node="0">کالبدشکافی فیزیکی و اپتیکی (اثبات تخصص):</b> هیچ ویژگی فنی نباید به صورت سطحی بیان شود. هر ادعای اپتیکی باید در ۳ الی ۴ پاراگراف از منظر فیزیک نور تشریح گردد. (مثال: هنگام بررسی «فاصلۀ کانونی کم در برابر فاصلۀ کانونی زیاد در قطر دهانۀ یکسان»، باید تأثیر آن بر انحنای آینه یا قطر عدسی، میزان شکست نور، اندازۀ تصویر، روشنایی تصویر در عکاسی، عمق میدان، خطای انحنای میدان و توان تفکیک به طور کامل کالبدشکافی شود).</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="31,2,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="31,2,0" data-index-in-node="0">مثال‌های رصدی و کاربردی ملموس (اثبات تجربه):</b> مفاهیم تئوری باید با مثال‌های عملی رصد آسمان یا طبیعت‌گردی همراه شوند. به جای جملۀ کلی «این ابزار کیفیت بالایی دارد»، باید تشریح شود که این کیفیت در رصد «اقمار مشتری، هلال زهره، شکاف کاسینی در حلقه‌های زحل یا سحابی جبار»، بررسی وضعیت «قرص ایری (Airy Disk)» از ۱ تا ۱۰ برای سنجش دید نجومی، یا در دوربین‌های دوچشمی برای «مشاهدۀ جزئیات پرهای پرنده و بال پروانه در فاصلۀ ۴/۵ تا ۵ متری (فوکوس نزدیک)» و «رصد پرستوی دریایی روی قایق پرتلاطم» چگونه عمل می‌کند.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="31,3,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="31,3,0" data-index-in-node="0">بسط فرمول‌های محاسباتی اپتیک:</b> در مقالات جامع آموزشی و راهنمای خرید، نویسنده موظف است فرمول‌های استاندارد پایگاه دانش را مطرح کرده و حتماً با یک <b data-path-to-node="31,3,0" data-index-in-node="144">مثال عددی واقعی</b> حل کند:</p><ul data-path-to-node="31,3,1" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="31,3,1,0,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="31,3,1,0,0" data-index-in-node="0">بزرگ‌نمایی تلسکوپ:</b> <span class="math-inline" data-math="M = F_o / F_e" data-index-in-node="19">$M = F_o / F_e$</span> (تقسیم فاصلۀ کانونی شیئی بر چشمی) و <b data-path-to-node="31,3,1,0,0" data-index-in-node="69">بیشینۀ بزرگ‌نمایی مفید:</b> ۲ برابر قطر دهانه به میلی‌متر.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="31,3,1,1,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="31,3,1,1,0" data-index-in-node="0">نسبت کانونی:</b> <span class="math-inline" data-math="f = F / D" data-index-in-node="13">$f = F / D$</span> و مقایسۀ سرعت دو ابزار از طریق فرمول <span class="math-inline" data-math="L_1 / L_2 = (f_2 / f_1)^2" data-index-in-node="60">$L_1 / L_2 = (f_2 / f_1)^2$</span>.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="31,3,1,2,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="31,3,1,2,0" data-index-in-node="0">مردمک خروجی (Exit Pupil):</b> در دوچشمی از تقسیم قطر دهانه بر بزرگ‌نمایی، و در تلسکوپ از تقسیم فاصلۀ کانونی چشمی بر نسبت کانونی تلسکوپ (با تأکید بر محدودیت ۷ میلی‌متری مردمک چشم انسان در تاریکی).</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="31,3,1,3,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="31,3,1,3,0" data-index-in-node="0">توان گردآوری نور:</b> <span class="math-inline" data-math="W = (D / 6)^2" data-index-in-node="18">$W = (D / 6)^2$</span> نسبت به چشم انسان و مقایسۀ دو ابزار با مجذور نسبت قطر دهانه‌ها.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="31,3,1,4,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="31,3,1,4,0" data-index-in-node="0">میدان دید:</b> رابطۀ میدان دید واقعی و ظاهری (<span class="math-inline" data-math="TFOV = AFOV / M" data-index-in-node="42">$TFOV = AFOV / M$</span>) و تبدیل میدان دید زاویه‌ای به میدان دید خطی در ۱۰۰۰ متر با ضریب ۱۷/۴۵ (یا ۱۷/۵).</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="31,3,1,5,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="31,3,1,5,0" data-index-in-node="0">توان تفکیک و حد قدر:</b> فرمول‌های حد ریلی (<span class="math-inline" data-math="5.5 / D_{\text{inch}}" data-index-in-node="40">$5.5 / D_{\text{inch}}$</span>)، حد داوز (<span class="math-inline" data-math="4.56 / D_{\text{inch}}" data-index-in-node="73">$4.56 / D_{\text{inch}}$</span>)، فرمول توان تفکیک در نور مرئی (<span class="math-inline" data-math="125 / D" data-index-in-node="128">$125 / D$</span>) و فرمول حد قدر (<span class="math-inline" data-math="5 \times \log_{10}(D_{\text{cm}}) + 7.5" data-index-in-node="153">$5 \times \log_{10}(D_{\text{cm}}) + 7.5$</span>).</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="31,3,1,6,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="31,3,1,6,0" data-index-in-node="0">فرمول‌های تخصصی دوچشمی و میکروسکوپ:</b> ضریب تاریک-روشنی (<span class="math-inline" data-math="\sqrt{M \times D}" data-index-in-node="54">$\sqrt{M \times D}$</span>) در دوچشمی‌ها، و فرمول حد تفکیک میکروسکوپ (<span class="math-inline" data-math="R = \frac{0.61 \lambda}{N.A}" data-index-in-node="115">$R = \frac{0.61 \lambda}{N.A}$</span>) و ضریب گشادگی (<span class="math-inline" data-math="N.A = n \cdot \sin\alpha" data-index-in-node="160">$N.A = n \cdot \sin\alpha$</span>) به همراه تحلیل تفاوت عدسی‌های شیئی خشک و ایمرسیون روغنی.</p></li></ul></li></ul><h3 data-path-to-node="32" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">۳. معماری خوشه‌های محتوایی (Topic Clusters) و لینک‌سازی داخلی</h3><p data-path-to-node="33" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">یک مقالۀ تنها برای مرجع شدن کافی نیست. محتوای سایت باید در قالب خوشه‌های موضوعی سازمان‌دهی شود:</p><ul data-path-to-node="34" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="34,0,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="34,0,0" data-index-in-node="0">مقالات ستون فقرات (Pillar Pages):</b> مقالات جامع و مرجع (بالای ۲۰۰۰ تا ۳۰۰۰ کلمه) که یک موضوع اصلی را به صورت ۳۶۰ درجه پوشش می‌دهند.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="34,1,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="34,1,0" data-index-in-node="0">مقالات خوشه‌ای (Clusters):</b> مقالات تخصصی فرعی که هر کدام یک جنبۀ خاص (مثلاً «مقایسۀ چشمی هویگنس و رامزدن» یا «تأثیر کندانسور و دیافراگم آیریس در کنتراست میکروسکوپ») را بررسی می‌کنند.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="34,2,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="34,2,0" data-index-in-node="0">لینک‌سازی داخلی استراتژیک:</b> ارتباط میان مقالات پایلار، کلاستر و صفحات محصول باید با <b data-path-to-node="34,2,0" data-index-in-node="83">انکرتکست‌های (Anchor Text) دقیق و توصیفی</b> انجام شود. استفاده از عبارات مبهم مانند «اینجا کلیک کنید» ممنوع است.</p></li></ul><h2 data-path-to-node="36" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">بخش سوم: معماری نگارش، خوانایی (Readability) و انسان‌نویسی (Humanizing)</h2><p data-path-to-node="37" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">طبق ماتریس لحن، حوزۀ فعالیت «آسمان شب» ترکیبی از <b data-path-to-node="37" data-index-in-node="49">تکنولوژی و دانش علمی</b> است؛ بنابراین لحن محتوا باید <b data-path-to-node="37" data-index-in-node="99">«آموزشی، دقیق، قاطع، علمی و بدون حاشیه»</b> باشد و در عین حال، از نظر ساختاری ۱۰۰٪ انسانی و خوانا نگارش شود:</p><h3 data-path-to-node="38" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">۱. قوانین انسان‌نویسی و حذف الگوهای رباتی (Anti-AI Patterns)</h3><ol start="1" data-path-to-node="39" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="39,0,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="39,0,0" data-index-in-node="0">خط قرمز واژگان رباتی:</b> استفاده از عبارات کلیشه‌ای و ماشینی نظیر <i data-path-to-node="39,0,0" data-index-in-node="63">«بی‌شک»، «در دنیای پرشتاب امروزی»، «حائز اهمیت است»، «شایان ذکر است»، «علاوه بر این»</i> و <i data-path-to-node="39,0,0" data-index-in-node="150">«در نهایت باید گفت»</i> در مقالات آسمان شب اکیداً ممنوع است.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="39,1,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="39,1,0" data-index-in-node="0">شکستن ریتم مکانیکی (Burstiness):</b> پاراگراف‌ها و جملات نباید هم‌اندازه و یکنواخت باشند. نویسنده باید ریتم طبیعی کلام را با الگوی ترکیبی حفظ کند: <b data-path-to-node="39,1,0" data-index-in-node="143">[یک جملۀ کوتاه و کوبندۀ علمی] + [یک جملۀ متوسط] + [یک جملۀ طولانی و تشریحی همراه با مثال رصدی یا آزمایشگاهی]</b>.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="39,2,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="39,2,0" data-index-in-node="0">انسجام و جریان متن (Flow):</b> انتقال از یک زیرتیتر به زیرتیتر بعدی باید کاملاً منطقی و نرم باشد تا رشتۀ کلام از دست خواننده خارج نشود.</p></li></ol><h3 data-path-to-node="40" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">۲. مهندسی اسکن‌پذیری (Scannability) و چیدمان بصری</h3><p data-path-to-node="41" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">از آنجا که کاربران وب متن را اسکن می‌کنند و دیوارهای طولانی متن (Wall of Text) باعث افزایش نرخ پرش (Bounce Rate) می‌شوند، رعایت قواعد زیر الزامی است:</p><ul data-path-to-node="42" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="42,0,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="42,0,0" data-index-in-node="0">قانون ۳ خط در پاراگراف:</b> هیچ پاراگرافی نباید در نمای موبایل بیش از ۳ الی ۴ خط باشد. هر پاراگراف باید تنها حول یک ایدۀ واحد بچرخد.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="42,1,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="42,1,0" data-index-in-node="0">سلسله‌مراتب منطقی هدینگ‌ها (H1 تا H4):</b> ساختار تیترها نقشۀ راه ربات گوگل و چشم کاربر است. استفاده از <code data-path-to-node="42,1,0" data-index-in-node="100">H3</code> بدون وجود <code data-path-to-node="42,1,0" data-index-in-node="113">H2</code> قبلی ممنوع است. هدینگ‌ها باید توصیفی و جذاب باشند (مثلاً به جای تیتر مبهم «نکات مهم»، نوشته شود: «۷ ویژگی کلیدی در انتخاب دوربین دوچشمی نجومی»).</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="42,2,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="42,2,0" data-index-in-node="0">استاندارد بولت‌پوینت‌گذاری (Bullet Points):</b></p><ul data-path-to-node="42,2,1" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="42,2,1,0,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">در مقالات بالای ۵۰۰ کلمه حداقل ۱ تا ۲ لیست، و در مقالات جامع بالای ۲۰۰۰ کلمه وجود <b data-path-to-node="42,2,1,0,0" data-index-in-node="82">۳ تا ۵ لیست</b> الزامی است.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="42,2,1,1,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">برای موارد غیرترتیبی (مثل ویژگی‌های دوچشمی شکاری) از <b data-path-to-node="42,2,1,1,0" data-index-in-node="53">لیست نقطه‌ای</b> و برای مراحل ترتیبی (مثل مراحل هم‌خط‌سازی آینه‌های تلسکوپ نیوتونی یا تنظیم شاریوت میکروسکوپ) از <b data-path-to-node="42,2,1,1,0" data-index-in-node="162">لیست شماره‌دار</b> استفاده شود.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="42,2,1,2,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="42,2,1,2,0" data-index-in-node="0">طول بهینۀ هر لیست بین ۳ تا ۷ آیتم است.</b> لیست‌های ۲ آیتمی باید در قالب جمله نوشته شوند و لیست‌های بیش از ۱۰ آیتم باید با زیرعنوان‌های <code data-path-to-node="42,2,1,2,0" data-index-in-node="132">H3</code> به دسته‌های کوچک‌تر تقسیم گردند.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="42,2,1,3,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><i data-path-to-node="42,2,1,3,0" data-index-in-node="0">قانون عدم افراط:</i> لیست‌ها مکمل پاراگراف‌ها هستند نه جایگزین آن‌ها؛ مقاله‌ای که تماماً بولت‌پوینت باشد، ساختار علمی و روایی خود را از دست می‌دهد.</p></li></ul></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="42,3,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="42,3,0" data-index-in-node="0">جداول مقایسه‌ای و تحلیل پس از جدول:</b> برای مقایسۀ مشخصات فنی (مانند مقایسۀ منشور جانبی Porro و مستقیم Roof، یا مقایسۀ ضریب گشادگی <span class="math-inline" data-math="N.A" data-index-in-node="128">$N.A$</span> و حد تفکیک در عدسی‌های شیئی آکروماتیک، فلوریت و آپوکروماتیک با بزرگ‌نمایی‌های ۴، ۱۰، ۴۰ و ۱۰۰ برابر) استفاده از جدول الزامی است. <b data-path-to-node="42,3,0" data-index-in-node="261">قانون قطعی:</b> بلافاصله پس از هر جدول، نویسنده موظف است ۲ تا ۳ پاراگراف مفصل در تحلیل داده‌های جدول و نتیجه‌گیری عملی برای راهنمایی خریدار بنویسد.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="42,4,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="42,4,0" data-index-in-node="0">برجسته‌سازی هدفمند (Bold):</b> بولد کردن کل یک جمله ممنوع است؛ تنها مفاهیم کلیدی و اصطلاحات مهم در هر پاراگراف باید پررنگ شوند.</p></li></ul><h2 data-path-to-node="44" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">بخش چهارم: شیوه‌نامۀ اختصاصی واژگان اپتیکی و ویراستاری صوری «آسمان شب»</h2><p data-path-to-node="45" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">تمامی محتواهای متنی وب‌سایت باید از نظر واژگان تخصصی و نگارش صوری، ۱۰۰٪ یکدست و منطبق بر استانداردهای مصوب مؤسسه باشند:</p><h3 data-path-to-node="46" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">۱. الزام استفاده از واژه‌نامۀ مصوب اپتیکی</h3><p data-path-to-node="47" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">نویسندگان حق استفاده از ترجمه‌های سلیقه‌ای را ندارند و باید منحصراً از معادل‌های فارسی مصوب «آسمان شب» استفاده کنند:</p><ul data-path-to-node="48" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,0,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,0,0" data-index-in-node="0">Aperture:</b> گشودگی دهانه / روزنه</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,1,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,1,0" data-index-in-node="0">Optical Tube:</b> لولۀ اپتیکی / راستۀ نور</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,2,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,2,0" data-index-in-node="0">Finder Scope:</b> جوینده (و <code data-path-to-node="48,2,0" data-index-in-node="24">Red-dot finder</code>: جویندۀ نقطه‌قرمز)</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,3,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,3,0" data-index-in-node="0">Eyepiece / Ocular:</b> چشمی (و <code data-path-to-node="48,3,0" data-index-in-node="27">Eyepiece Holder</code>: جاچشمی)</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,4,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,4,0" data-index-in-node="0">Objective:</b> عدسی شیئی</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,5,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,5,0" data-index-in-node="0">Exit Pupil:</b> مردمک خروجی</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,6,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,6,0" data-index-in-node="0">Eye Relief:</b> فاصلۀ آسودگی چشم</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,7,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,7,0" data-index-in-node="0">Focal Ratio:</b> نسبت کانونی</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,8,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,8,0" data-index-in-node="0">Focal Reducer:</b> کانون‌کاه</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,9,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,9,0" data-index-in-node="0">Collimation:</b> هم‌خط‌سازی (و <code data-path-to-node="48,9,0" data-index-in-node="27">Collimator</code>: هم‌خط‌ساز)</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,10,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,10,0" data-index-in-node="0">Mount:</b> مقر (<code data-path-to-node="48,10,0" data-index-in-node="12">Alt-Az Mount</code>: استقرار سمتی-ارتفاعی / <code data-path-to-node="48,10,0" data-index-in-node="49">Equatorial</code>: استوایی)</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,11,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,11,0" data-index-in-node="0">GoTo:</b> جرم‌یاب خودکار</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,12,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,12,0" data-index-in-node="0">Guide Scope:</b> گایداسکوپ (تلسکوپ راهنما)</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,13,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,13,0" data-index-in-node="0">Diagonal:</b> چپقی (<code data-path-to-node="48,13,0" data-index-in-node="16">Mirror diagonal</code>: چپقی آینه‌ای / <code data-path-to-node="48,13,0" data-index-in-node="48">Prism Diagonal</code>: چپقی منشوری)</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,14,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,14,0" data-index-in-node="0">Coating:</b> اندود / پوشينه (مانند: «اندود چندلایه و کامل» برای <code data-path-to-node="48,14,0" data-index-in-node="60">FMC</code>)</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,15,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,15,0" data-index-in-node="0">Correcting Plate:</b> تیغۀ تصحیح</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,16,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,16,0" data-index-in-node="0">Dovetail bar:</b> رابط یا صفحۀ اتصال دم‌چلچله‌ای</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,17,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,17,0" data-index-in-node="0">Baffle:</b> موج‌گیر</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,18,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,18,0" data-index-in-node="0">Backlash:</b> لقّی</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,19,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,19,0" data-index-in-node="0">Seeing:</b> دید نجومی (و <code data-path-to-node="48,19,0" data-index-in-node="21">Scintillation</code>: سوسوزنی)</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,20,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,20,0" data-index-in-node="0">Twilight Factor:</b> ضریب تاریک-روشنی</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,21,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,21,0" data-index-in-node="0">Near Focus:</b> فوکوس نزدیک (نزدیک‌ترین فاصلۀ فوکوس)</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,22,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,22,0" data-index-in-node="0">Interpupillary Distance:</b> بازۀ بین دو مردمک چشمی</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="48,23,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="48,23,0" data-index-in-node="0">Revolver (در میکروسکوپ):</b> صفحۀ گردان (قطعۀ دماغی چرخنده)</p></li></ul><h3 data-path-to-node="49" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">۲. قانون نگارش نام برندها و واژگان لاتین</h3><ul data-path-to-node="50" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="50,0,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">تا جای ممکن باید از نگارش واژه‌ها و حروف لاتین در میان متن فارسی پرهیز شود.</p></li><li dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><p data-path-to-node="50,1,0" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;"><b data-path-to-node="50,1,0" data-index-in-node="0">قانون اولیه‌نگاری:</b> نام برندها، کمپانی‌ها یا ساختارهای خاص، <b data-path-to-node="50,1,0" data-index-in-node="59">تنها در اولین مرتبه</b> در متن به صورت «تلفظ فارسی + (نام انگلیسی در پرانتز)» درج می‌شوند؛ مانند: «اسکای‌واچر (Sky-Watcher)»، «سلسترون (Celestron)» یا «منشور جانبی (Porro)». در تمامی دفعات بعدی در طول همان متن، <b data-path-to-node="50,1,0" data-index-in-node="266">صرفاً تلفظ فارسی</b> (اسکای‌واچر، سلسترون، منشور جانبی) بدون حروف لاتین نوشته می‌شود.</p></li></ul><h3 data-path-to-node="51" dir="rtl" style="direction: rtl; text-align: right; unicode-bidi: isolate;">۳. قوانین ویرایش صوری (مبتنی بر شیوه‌نامۀ علی آزادگان)</h3><p data-path-to-node="1" dir="rtl" style="text-align: right;"></p><ol start="1" data-path-to-node="52" dir="rtl"><li dir="rtl" style="text-align: right;"><p data-path-to-node="52,0,0" dir="rtl" style="text-align: right;"><b data-path-to-node="52,0,0" data-index-in-node="0">رعایت دقیق نیم‌فاصله (<code data-path-to-node="52,0,0" data-index-in-node="22">Ctrl+Shift+2</code>):</b> در تمامی پسوندهای جمع («ها» مانند: تلسکوپ‌ها، چشمی‌ها)، پیشوندهای افعال («می» و «نمی» مانند: می‌چرخد، نمی‌تواند)، صفت‌های تفضیلی و عالی («تر» و «ترین» مانند: شفاف‌تر، بزرگ‌ترین) و واژگان مرکب (مانند: بزرگ‌نمایی، پرنده‌نگری، هم‌خط‌سازی، سه‌پایه) رعایت نیم‌فاصله الزامی است.</p></li></ol>', '/mag/uploads/2026/10/img_1792233682_d20b1cb6.webp', 'کاور مقالات', '0', 'درد، ستون فقرات و توانبخشی', 'stethoscope', 'dr-radmanesh', '{"name": "دکتر مهران رادمنش", "title": "متخصص جراحی مغز، اعصاب و ستون فقرات", "avatar": "https://images.unsplash.com/photo-1622253692010-333f2da6031d?auto=format&fit=crop&w=200&q=80"}'::jsonb, '13 دقیقه', 'امروز', 'مقاله علمی', 'tag-blue', 'published', 'راهنمای بالینی درمان غیرجراحی دیسک کمر و سیاتیک | مجله پزشکآن', 'بررسی علمی راهکارهای نوین توانبخشی و مداخله‌ای بدون نیاز به بیهوشی و تیغ جراحی، همراه با معیارهای تریاژ اورژانس سندرم دم اسب.', 'درمان غیرجراحی دیسک کمر', '[{"q": "آیا استراحت مطلق در بستر برای درمان دیسک کمر مفید است؟", "a": "خیر؛ استراحت بیش از ۴۸ ساعت موجب ضعف عضلات پارااسپینال می‌شود."}, {"q": "چند جلسه فیزیوتراپی پیشرفته لازم است؟", "a": "معمولاً دوره استاندارد شامل ۱۰ الی ۱۵ جلسه درمانی است."}]'::jsonb, 'MedicalWebPage', '[]'::jsonb, '{"syncTitle": true, "syncDesc": true, "headline": "راهنمای بالینی درمان غیرجراحی دیسک کمر و سیاتیک: از شاک‌ویو تا لیزر پرتوان", "description": "بررسی علمی راهکارهای نوین توانبخشی و مداخله‌ای بدون نیاز به بیهوشی و تیغ جراحی، همراه با معیارهای تریاژ اورژانس سندرم دم اسب.", "reviewer": "دکتر مهران رادمنش (نظام پزشکی: ۱۱۴۲۸۵)", "specialty": "GeneralPractice, ClinicalMedicine", "audience": "Patients", "howtoSteps": []}'::jsonb, '')
