INSERT INTO pezeshkan_articles (title, slug, summary, raw_html, content_html, image, image_alt, pillar_id, category_name, category_icon, doctor_id, author, read_time, last_reviewed, tag, tag_class, status, meta_title, meta_description, focus_keyword, faqs, schema_type, old_slugs, schema_data, custom_schema_json)
VALUES ('غربالگری سه ماهه اول بارداری: مقایسه تست ترکیبی با آزمایش ژنتیک سل‌فری (NIPT)', 'first-trimester-screening-ultrasound-nipt', 'راهنمای گام‌به‌گام مادران برای سنجش سونوگرافی NT، آزمایش‌های بیوشیمیایی و سل‌فری DNA جهت تشخیص زودهنگام ناهنجاری‌های کروموزومی.', '<h2>زمان طلایی انجام غربالگری سه ماهه اول</h2><p>دقیق‌ترین پنجره زمانی برای انجام سونوگرافی NT و آزمایش خون دابل مارکر (Free-Beta-hCG و PAPP-A) بین هفته ۱۱ تا ۱۳ هفته و ۶ روز بارداری است که طول سری-دمی جنین (CRL) بین ۴۵ تا ۸۴ میلی‌متر قرار دارد.</p><figure class="clinical-img-figure"><img src="https://images.unsplash.com/photo-1584515979956-d9f6e5d09982?auto=format&fit=crop&w=800&q=80" alt="سونوگرافی غربالگری جنین در کلینیک زنان و زایمان"><figcaption class="clinical-img-caption">سونوگرافی غربالگری ناهنجاری‌های کروموزومی در کلینیک زنان</figcaption></figure><h2>تفاوت تست سل‌فری (NIPT) با غربالگری معمول</h2><p>آزمایش NIPT با ایزوله‌سازی قطعات DNA آزاد جنینی در گردش خون مادر عمل می‌کند. دقت این تست برای تریزومی ۲۱ (سندرم داون) بیش از ۹۹ درصد با نرخ مثبت کاذب کمتر از ۰.۱ درصد است.</p><div class="clinical-callout advice"><div class="callout-header"><svg xmlns=''http://www.w3.org/2000/svg'' width=''15'' height=''15'' viewBox=''0 0 24 24'' fill=''none'' stroke=''currentColor'' stroke-width=''2.2'' style=''vertical-align:middle;''><path d=''M11 2v2M5 2v2m0-1H4a2 2 0 0 0-2 2v4a6 6 0 0 0 12 0V5a2 2 0 0 0-2-2h-1''/><path d=''M8 15a6 6 0 0 0 12 0v-3''/><circle cx=''20'' cy=''10'' r=''2''/></svg> توصیه تخصصی پریناتولوژی</div><div>انجام تست NIPT برای تمامی مادران باردار به ویژه بالای ۳۵ سال یا سابقه ناهنجاری کروموزومی توصیه اکید می‌گردد.</div></div>', NULL, 'https://images.unsplash.com/photo-1584515979956-d9f6e5d09982?auto=format&fit=crop&w=800&q=80', 'سونوگرافی غربالگری جنین در کلینیک زنان و زایمان', NULL, NULL, NULL, NULL, '{"name": "تیم متخصص محتوا نویس پزشکآن", "title": "تحریریه علمی و شورای پایش بالینی مجله سلامت پزشکآن", "avatar": "https://images.unsplash.com/photo-1622253692010-333f2da6031d?auto=format&fit=crop&w=200&q=80", "badge": "دارای تأییدیه علمی و استناد به منابع معتبر"}'::jsonb, '۶ دقیقه', '۲۵ شهریور ۱۴۰۵', NULL, NULL, 'published', 'غربالگری سه ماهه اول بارداری؛ مقایسه تست ترکیبی و NIPT | پزشکآن', 'راهنمای جامع مادران برای سونوگرافی NT، دابل مارکر و آزمایش DNA آزاد جنینی (سل‌فری NIPT) با دقت بالای ۹۹ درصد.', 'غربالگری سه ماهه اول بارداری', '[{"q": "آیا آزمایش سل‌فری نیاز به ناشتا بودن دارد؟", "a": "خیر، نیازی به ناشتایی ندارد اما مصرف آب کافی توصیه می‌شود."}]'::jsonb, 'MedicalWebPage', '[]'::jsonb, '{}'::jsonb, NULL)
ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_html = EXCLUDED.content_html, last_modified = NOW();
INSERT INTO pezeshkan_articles (title, slug, summary, raw_html, content_html, image, image_alt, pillar_id, category_name, category_icon, doctor_id, author, read_time, last_reviewed, tag, tag_class, status, meta_title, meta_description, focus_keyword, faqs, schema_type, old_slugs, schema_data, custom_schema_json)
VALUES ('تریاژ دردهای حاد قفسه سینه: تمایز بین حمله قلبی، ریفلاکس معده و اسپاسم عضلانی', 'chest-pain-triage-heart-attack-vs-gastric', 'دستورالعمل بالینی تصمیم‌گیری سریع هنگام احساس درد در جناغ سینه؛ چه زمانی بلافاصله با اورژانس ۱۱۵ تماس بگیریم؟', '<h2>مشخصات بالینی درد ایسکمیک قلبی</h2><p>درد قلبی معمولاً احساس فشار سنگین، سوزش مبهم یا فشردن قفسه سینه است که ممکن است به فک، گردن، شانه چپ، پشت یا هر دو بازو انتشار یابد و همراه با تنگی نفس، تعریق سرد، تهوع یا سرگیجه باشد.</p><div class="clinical-callout warning"><div class="callout-header"><svg xmlns=''http://www.w3.org/2000/svg'' width=''15'' height=''15'' viewBox=''0 0 24 24'' fill=''none'' stroke=''currentColor'' stroke-width=''2.2'' style=''vertical-align:middle;''><path d=''M7 18v-6a5 5 0 1 1 10 0v6''/><path d=''M5 21a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1v-1a2 2 0 0 0-2-2H7a2 2 0 0 0-2 2z''/></svg> کد قرمز تریاژ اورژانس</div><div>درد فشارنده قفسه سینه بیش از ۵ دقیقه همراه با تعریق سرد یک فوریت پزشکی است. بلافاصله با شماره ۱۱۵ تماس بگیرید و از رانندگی شخصی خودداری کنید.</div></div><h2>دردهای گوارشی و اسکلتی-عضلانی</h2><p>دردهای ناشی از ریفلاکس مری (GERD) با سوزش پشت جناغ پس از غذا و در حالت خوابیده تشدید می‌شوند. دردهای دیواره قفسه سینه (کاستوکندریت) با لمس موضعی یا نفس عمیق تغییر شدت می‌دهند.</p>', NULL, 'https://images.unsplash.com/photo-1628348068343-c6a848d2b6dd?auto=format&fit=crop&w=800&q=80', 'گوشی پزشکی و نوار قلب مانیتورینگ بیمار قلبی', NULL, NULL, NULL, NULL, '{"name": "تیم متخصص محتوا نویس پزشکآن", "title": "تحریریه علمی و شورای پایش بالینی مجله سلامت پزشکآن", "avatar": "https://images.unsplash.com/photo-1622253692010-333f2da6031d?auto=format&fit=crop&w=200&q=80", "badge": "دارای تأییدیه علمی و استناد به منابع معتبر"}'::jsonb, '۵ دقیقه', '۲۶ شهریور ۱۴۰۵', NULL, NULL, 'published', 'تریاژ دردهای حاد قفسه سینه: تمایز حمله قلبی از ریفلاکس | پزشکآن', 'دستورالعمل بالینی افتراق دردهای قلبی ایسکمیک از مشکلات گوارشی و عضلانی به همراه اقدامات طلایی در ۶۰ دقیقه اول.', 'درد قفسه سینه', '[{"q": "آیا درد قفسه سینه در زنان علائم متفاوتی دارد؟", "a": "بله؛ زنان ممکن است با خستگی مفرط، تنگی نفس یا درد بالای شکم مراجعه کنند."}]'::jsonb, 'MedicalWebPage', '[]'::jsonb, '{}'::jsonb, NULL)
ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_html = EXCLUDED.content_html, last_modified = NOW();
INSERT INTO pezeshkan_articles (title, slug, summary, raw_html, content_html, image, image_alt, pillar_id, category_name, category_icon, doctor_id, author, read_time, last_reviewed, tag, tag_class, status, meta_title, meta_description, focus_keyword, faqs, schema_type, old_slugs, schema_data, custom_schema_json)
VALUES ('تزریق پی‌آر‌پی (PRP) زانو؛ معجزه غضروف‌سازی یا تسکین موقت آرتروز؟', 'prp-knee-osteoarthritis-injection', 'بررسی شواهد علمی اثر پلاسمای غنی از پلاکت در مهار سایش مفصل زانو، دوز تزریق و اقدامات پس از تزریق پزشک.', '<h2 dir="rtl" style="direction: rtl; unicode-bidi: isolate; text-align: right;">مکانیسم اثر پلاسمای غنی از پلاکت در مفصل</h2><p dir="rtl" style="direction: rtl; unicode-bidi: isolate; text-align: right;">پلاسمای غنی از پلاکت (PRP) با فعال‌سازی گرانول‌های آلفا و آزادسازی فاکتورهای رشد فیبروبلاستی (FGF) و تبدیل‌کننده بتا (TGF-beta)، باعث مهار متالوپروتئینازها و کاهش روند تخریب کندروسیت‌های مفصلی می‌شود.</p><figure class="clinical-img-figure"><img src="https://images.unsplash.com/photo-1576091160550-2173dba999ef?auto=format&amp;fit=crop&amp;w=800&amp;q=80" alt="معاینه مفصل زانو توسط پزشک ارتوپد"><figcaption class="clinical-img-caption">ارزیابی دقیق درجه‌بندی کلگرن-لارنس (Kellgren-Lawrence) آرتروز زانو</figcaption></figure><h2 dir="rtl" style="direction: rtl; unicode-bidi: isolate; text-align: right;">پروتکل تزریق و مراقبت‌های پس از آن</h2><p dir="rtl" style="direction: rtl; unicode-bidi: isolate; text-align: right;">تزریق باید ترجیحاً تحت هدایت سونوگرافی داخل مفصلی صورت گیرد. بیمار باید از مصرف مسکن‌های ضدالتهاب غیراستروئیدی (NSAIDs) مانند ژلوفن به مدت دو هفته قبل و بعد از پروسیجر خودداری کند تا فرآیند طبیعی التیام پلاکت‌ها مختل نشود.</p><blockquote style="direction: rtl; unicode-bidi: isolate; text-align: center;" dir="rtl" data-align="center" class="text-center">بیشتر بخوانید:&nbsp;<a href="https://prpiran.com/" target="_blank" rel="noopener noreferrer" class="editorial-link" style="font-family: Vazirmatn, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, sans-serif;">پی آر پی ایران</a></blockquote>', '<h2 dir="rtl" style="direction: rtl; unicode-bidi: isolate; text-align: right;">مکانیسم اثر پلاسمای غنی از پلاکت در مفصل</h2><p dir="rtl" style="direction: rtl; unicode-bidi: isolate; text-align: right;">پلاسمای غنی از پلاکت (PRP) با فعال‌سازی گرانول‌های آلفا و آزادسازی فاکتورهای رشد فیبروبلاستی (FGF) و تبدیل‌کننده بتا (TGF-beta)، باعث مهار متالوپروتئینازها و کاهش روند تخریب کندروسیت‌های مفصلی می‌شود.</p><figure class="clinical-img-figure"><img src="https://images.unsplash.com/photo-1576091160550-2173dba999ef?auto=format&amp;fit=crop&amp;w=800&amp;q=80" alt="معاینه مفصل زانو توسط پزشک ارتوپد"><figcaption class="clinical-img-caption">ارزیابی دقیق درجه‌بندی کلگرن-لارنس (Kellgren-Lawrence) آرتروز زانو</figcaption></figure><h2 dir="rtl" style="direction: rtl; unicode-bidi: isolate; text-align: right;">پروتکل تزریق و مراقبت‌های پس از آن</h2><p dir="rtl" style="direction: rtl; unicode-bidi: isolate; text-align: right;">تزریق باید ترجیحاً تحت هدایت سونوگرافی داخل مفصلی صورت گیرد. بیمار باید از مصرف مسکن‌های ضدالتهاب غیراستروئیدی (NSAIDs) مانند ژلوفن به مدت دو هفته قبل و بعد از پروسیجر خودداری کند تا فرآیند طبیعی التیام پلاکت‌ها مختل نشود.</p><blockquote style="direction: rtl; unicode-bidi: isolate; text-align: center;" dir="rtl" data-align="center" class="text-center">بیشتر بخوانید:&nbsp;<a href="https://prpiran.com/" target="_blank" rel="noopener noreferrer" class="editorial-link" style="font-family: Vazirmatn, -apple-system, BlinkMacSystemFont, &quot;Segoe UI&quot;, Roboto, sans-serif;">پی آر پی ایران</a></blockquote>', 'https://images.unsplash.com/photo-1576091160550-2173dba999ef?auto=format&fit=crop&w=800&q=80', 'معاینه مفصل زانو توسط پزشک ارتوپد در کلینیک', '0', 'درد، ستون فقرات و توانبخشی', 'stethoscope', 'dr-radmanesh', '{"name": "تیم متخصص محتوا نویس پزشکآن", "title": "تحریریه علمی و شورای پایش بالینی مجله سلامت پزشکآن", "avatar": "https://images.unsplash.com/photo-1622253692010-333f2da6031d?auto=format&fit=crop&w=200&q=80", "badge": "دارای تأییدیه علمی و استناد به منابع معتبر"}'::jsonb, '1 دقیقه', 'امروز', 'مقاله علمی', 'tag-blue', 'published', 'تزریق پی‌آر‌پی (PRP) زانو و درمان آرتروز مفصل | پزشکآن', 'بررسی شواهد علمی اثربخشی تزریق پلاسمای غنی از پلاکت (PRP) در کاهش دردهای آرتروز زانو و تسریع ترمیم غضروف.', 'پی‌آر‌پی زانو', '[{"q": "تزریق PRP چند جلسه نیاز دارد؟", "a": "معمولاً یک تا سه جلسه با فواصل ۳ الی ۴ هفته‌ای توصیه می‌شود."}]'::jsonb, 'MedicalWebPage', '[]'::jsonb, '{"syncTitle": true, "syncDesc": true, "headline": "تزریق پی‌آر‌پی (PRP) زانو؛ معجزه غضروف‌سازی یا تسکین موقت آرتروز؟", "description": "بررسی شواهد علمی اثر پلاسمای غنی از پلاکت در مهار سایش مفصل زانو، دوز تزریق و اقدامات پس از تزریق پزشک.", "reviewer": "دکتر احسان کریمی (نظام: ۸۹۴۳۲)", "specialty": "GeneralPractice, ClinicalMedicine", "audience": "Patients", "howtoSteps": []}'::jsonb, '')
